window.COMPANIES = [{"id":"masan","name":"Masan Consumer (Tập đoàn Masan)","program":"Masan Young Entrepreneur (MYE) – Sales Program","industry":"FMCG","lastChecked":"2026-11-13","summary":"Masan Young Entrepreneur – Sales Program là chương trình quản lý kinh doanh tập sự của Masan Consumer (mùa 2 năm 2026): luân chuyển thực tế qua các phòng ban Sales (GT, MT, Shopper) và lộ trình từng bước lên vị trí Giám sát (Sales Leader). Quy trình chính thức 4 vòng, kết thúc bằng Thuyết trình chuyên môn; yêu cầu sẵn sàng làm việc tại tỉnh.","intake":{"text":"MYE – Sales Program 2026: nộp đơn 07/05–07/06/2026; Kiểm tra năng lực 06/2026; Phỏng vấn sơ bộ 07/2026; Thuyết trình chuyên môn 07/2026. MYE – Sales Program 2025: nộp đơn 18/10–05/11/2025; Kiểm tra năng lực 11/2025; Phỏng vấn sơ bộ 11/2025; Thuyết trình chuyên môn 12/2025. Hai đợt gần nhất cách nhau khoảng 6 tháng (Q4/2025, Q2/2026) nên thời điểm thay đổi; đợt kế tiếp chưa công bố.","basis":"official","src":[0,1,2]},"eligibility":[{"text":"Sinh viên mới tốt nghiệp hoặc dưới 2 năm kinh nghiệm; GPA tích lũy từ 6.5/10 trở lên (MYE Sales 2025 và 2026).","basis":"official","src":[0,2]},{"text":"Đam mê Kinh doanh & Bán hàng, đặc biệt FMCG; sẵn sàng làm việc tại các tỉnh thành được chỉ định và sẵn sàng di chuyển, tiếp xúc, phát triển khách hàng tại các kênh.","basis":"official","src":[0,1]}],"functions":[{"text":"MYE – Sales Program 2026: luân chuyển qua các phòng ban Sales (GT, MT, Shopper), lộ trình hướng tới vị trí Giám sát (Sales Leader). Mùa 2025 nêu lộ trình 9–18 tháng để trở thành Giám sát Bán hàng.","basis":"official","src":[0,1,2]}],"stages":[{"name":"Vòng 1: Nộp đơn ứng tuyển","what":"Nộp đơn online (2026: 07/05–07/06/2026; 2025: 18/10–05/11/2025). (Theo chia sẻ ứng viên các mùa MT cũ, hồ sơ gồm CV, bảng điểm và application form — reported, mùa cũ, chưa xác minh.)","tips":["Nêu trải nghiệm bán hàng, kinh doanh nhỏ hoặc dự án có số liệu doanh số.","Ghi rõ sẵn sàng làm việc tại tỉnh và di chuyển thị trường."],"basis":"official","src":[0,2,3]},{"name":"Vòng 2: Kiểm tra năng lực","what":"Kiểm tra năng lực (2026: 06/2026; 2025: 11/2025). Hình thức (online hay tại chỗ, số phần, thời gian): Chưa có thông tin công khai đáng tin cậy.","tips":["Luyện Quant và DI với số liệu bán hàng (doanh số, thị phần, tăng trưởng).","Luyện Logical có bấm giờ."],"basis":"official","src":[0,2]},{"name":"Vòng 3: Phỏng vấn sơ bộ","what":"Phỏng vấn sơ bộ (2026: 07/2026; 2025: 11/2025). Hình thức chính thức chưa công bố. (Ứng viên các mùa MT cũ kể có phỏng vấn với HR và phỏng vấn nhóm với case study — reported, mùa cũ, chưa xác minh.)","tips":["Chuẩn bị câu chuyện STAR về nhiệt huyết, cầu tiến, kỷ luật, tinh thần học hỏi.","Ra cửa hàng tạp hóa/siêu thị quan sát cách trưng bày sản phẩm Masan để có ví dụ thực tế."],"basis":"official","src":[0,2,3]},{"name":"Vòng 4: Thuyết trình chuyên môn","what":"Thuyết trình chuyên môn (2026: 07/2026; 2025: 12/2025). Nội dung chính thức chưa công bố. (Ứng viên mùa MT cũ kể vòng cuối có khoảng 30 phút chuẩn bị và trình bày 3 slide về một vấn đề của phòng ban — reported, mùa cũ, chưa xác minh.)","tips":["Luyện dựng bài trình bày ngắn: vấn đề – phân tích số liệu – đề xuất hành động (mẹo dựa trên chia sẻ ứng viên cũ, reported).","Nắm các kênh GT/MT và khái niệm shopper marketing."],"basis":"official","src":[0,2,3]}],"tests":[{"name":"Kiểm tra năng lực","provider":null,"format":"Chưa có thông tin công khai đáng tin cậy về dạng câu hỏi và thời gian; Masan chỉ công bố tên vòng và tháng.","basis":"official","src":[0]}],"values":{"name":"Tố chất ứng viên MYE Sales (theo tin tuyển dụng 2025–2026)","items":["Nhiệt huyết","Cầu tiến","Kỷ luật","Tinh thần học hỏi cao","Đam mê Kinh doanh & Bán hàng (FMCG)"],"basis":"official","src":[0,2]},"prep":["Đọc Study guide phần DI và Quant, tập trung bài toán doanh số, % tăng trưởng, thị phần.","Mental math gym hằng ngày — tính nhanh là lợi thế khi phân tích số liệu bán hàng.","Làm 'Masan-style practice test' trong Mock test, sau đó luyện chủ đề SJT cho tình huống quản lý đội bán hàng.","Đi thực địa: quan sát 3–5 điểm bán (GT và MT), ghi lại cách trưng bày, giá, khuyến mãi các nhãn Masan.","Luyện một bài thuyết trình ngắn về case bán hàng có giới hạn thời gian chuẩn bị (dựa trên chia sẻ ứng viên cũ, reported).","Chuẩn bị câu trả lời thật lòng về việc làm ở tỉnh và lộ trình lên Giám sát.","Theo dõi kênh tuyển dụng Masan Consumer cả quý 2 và quý 4 vì thời điểm mở đơn thay đổi giữa các đợt."],"mock":{"title":"Masan-style practice test","topics":{"Quant":5,"Logical":4,"Verbal":3,"DI":6,"SJT":2},"minutes":25,"navigation":true,"note":"Masan chưa công bố định dạng vòng Kiểm tra năng lực; cấu hình nghiêng về DI/Quant vì chương trình Sales cần phân tích số liệu, thêm SJT cho tình huống quản lý. Vòng thuyết trình chuyên môn không mô phỏng được trong app.","basis":"general","src":[0]},"pitfalls":["Không sẵn sàng làm việc ở tỉnh nhưng vẫn ứng tuyển — đây là điều kiện công bố (official).","Đợi đúng mùa năm trước mới theo dõi: đợt 2025 mở tháng 10, đợt 2026 mở tháng 5 (official).","Thuyết trình dàn trải, quá nhiều slide khi thời gian chuẩn bị ngắn (reported từ ứng viên mùa cũ, chưa xác minh).","Dùng mô tả 5 vòng của các mùa MT cũ thay vì lịch 4 vòng chính thức của MYE Sales (general)."],"sources":[{"title":"[Toàn Quốc] Chương Trình Tuyển Dụng 'Masan Young Entrepreneur – Sales Program 2026'","url":"https://ybox.vn/tuyen-dung/toan-quoc-chuong-trinh-tuyen-dung-masan-young-entrepreneur-sales-program-2026-danh-cho-sinh-vien-moi-tot-nghiep-hoac-duoi-2-nam-kinh-nghiem-tai-tap-doan-hang-tieu-dung-nhanh-masan-69fe7ec073257002f74ee575","publisher":"YBOX (bài đăng của Masan Consumer)","year":"2026","accessed":"2026-11-13"},{"title":"Masan Young Entrepreneur - Sales Program 2026","url":"https://jobs.neu.edu.vn/jobs/masan-young-entrepreneur-sales-program-2026-masan-consumer-1202605111547","publisher":"Trung tâm Đổi mới sáng tạo và Hướng nghiệp - ĐH Kinh tế Quốc dân","year":"2026","accessed":"2026-11-13"},{"title":"[HCM/Miền Trung/Miền Nam] Chương Trình Tuyển Dụng Quản Lý Kinh Doanh Tập Sự Masan Young Entrepreneur – Sales Program 2025","url":"https://ybox.vn/tuyen-dung/hcm-mien-trung-mien-nam-chuong-trinh-tuyen-dung-quan-ly-kinh-doanh-tap-su-masan-young-entrepreneur-sales-program-2025-tai-tap-doan-hang-tieu-dung-nhanh-masan-68f5d640aa72e20d8c60fe90","publisher":"YBOX (bài đăng của Masan Consumer)","year":"2025","accessed":"2026-11-13"},{"title":"Masan Consumer Tuyển Dụng: Kinh Nghiệm Thi Management Trainee & Các Vị Trí Hot","url":"https://viecoi.vn/cam-nang-nghe-nghiep/chi-tiet-chia-se-kinh-nghiem-ve-chuong-trinh-tuyen-dung-management-trainee-cua-masan-consumer-986.html","publisher":"Viecoi.vn","year":"n/a","accessed":"2026-11-13"}]},{"id":"pg","name":"P&G Vietnam","program":"P&G LEAD GEN (internship-to-Management Trainee route)","industry":"FMCG","lastChecked":"2026-11-13","summary":"Tại Việt Nam, đường vào vị trí quản lý cấp đầu của P&G chủ yếu là P&G LEAD GEN: chương trình thực tập toàn thời gian có lương 6 tháng cho sinh viên đại học, người làm tốt có thể được đề nghị vị trí quản lý toàn thời gian sau đánh giá hiệu suất. P&G tuyển theo hướng 'hire from within', nên điểm khác biệt là bài đánh giá online chuẩn hoá toàn cầu (PEAK Performance Assessment và, tuỳ vị trí, Interactive Assessment), sau đó nhiều vòng phỏng vấn với quản lý cấp cao. Chưa thấy tin tuyển 'Management Trainee' riêng của P&G Việt Nam trong giai đoạn gần đây.","intake":{"text":"LEAD GEN 2026: theo tin trên YBOX, phần lớn track yêu cầu đi làm toàn thời gian từ tháng 1/2026 (riêng Process Engineer ghi từ tháng 7/2025; một số tin khác ghi tháng 5/2026); thời gian nhận đơn cụ thể chưa xác minh được (cổng VinUni ghi 29/10–12/11/2025 nhưng hiện không truy cập được). LEAD GEN 2027: các bài đăng cộng đồng/LinkedIn ghi hạn đợt 2 (Batch 2) là 23:59 ngày 31/10/2026, xét cuốn chiếu (reported); kiểm tra pgcareers.com xem còn đợt sau không. Nhìn chung đơn mở khoảng tháng 9–11 và xét theo thứ tự nộp, nên nộp sớm.","basis":"reported","src":[3,4,5]},"eligibility":[{"text":"Sinh viên đại học, hoặc đã học xong chương trình nhưng chưa nhận bằng.","basis":"official","src":[3]},{"text":"LEAD GEN 2026: làm việc toàn thời gian 6 tháng (đa số track từ tháng 1/2026); tiếng Anh tốt cả nói và viết; ưu tiên có kinh nghiệm thực tập.","basis":"official","src":[3]},{"text":"Trợ cấp được YBOX đăng là 12–17 triệu VND/tháng (LEAD GEN 2026); P&G chưa công bố con số trên trang chính thức.","basis":"reported","src":[3]}],"functions":[{"text":"Các track LEAD GEN 2026 trên YBOX: Sales, Brand, HR Analytics, Finance, Commercial IT (khối Commercial, TP.HCM) và Process Engineer (khối Manufacturing, nhà máy Bình Dương); một số trang việc làm khác đăng thêm Data & Automation / Data Engineer (reported).","basis":"official","src":[3,6]}],"stages":[{"name":"Online Application","what":"Nộp đơn trên pgcareers.com; theo tin LEAD GEN 2026 trên YBOX, đơn được xét theo nguyên tắc 'first come, first served'.","tips":["Nộp sớm ngay khi mở đơn vì xét cuốn chiếu và track có thể đủ người.","CV tiếng Anh 1 trang, mỗi gạch đầu dòng có kết quả định lượng."],"basis":"official","src":[3,2]},{"name":"Online Assessment Tests (PEAK Performance Assessment + Interactive Assessment)","what":"Sau khi nộp đơn, ứng viên có thể được mời làm một hoặc nhiều bài đánh giá online đo những kỹ năng mà phỏng vấn khó thấy. P&G cho biết cố gắng báo kết quả qua email trong vòng 30 ngày; nếu không đạt, phải chờ 12 tháng mới làm lại; với đa số vị trí, kết quả bài đánh giá tự động quyết định việc đi tiếp. PEAK (khoảng 20 phút) đánh giá nền tảng, kinh nghiệm, sở thích và thái độ làm việc so với năng lực của P&G; gồm 4 phần, nộp phần nào thì không quay lại sửa được. Tuỳ vị trí, có thêm Interactive Assessment (khoảng 30 phút, chuỗi bài đánh giá năng lực nhận thức ngắn).","tips":["Bài đánh giá rất quan trọng: trượt phải chờ 12 tháng mới làm lại, nên chỉ làm khi đã luyện và tỉnh táo.","PEAK: đọc kỹ từng câu trước khi nộp mỗi phần vì không quay lại được; trả lời trung thực, nhất quán; phải tự làm, không nhờ người khác hay dùng AI.","Interactive Assessment: luyện các dạng game nhận thức (suy luận, tính nhẩm, trí nhớ không gian) có bấm giờ.","Kiểm tra email (cả thư rác) để không lỡ link đánh giá và kết quả."],"basis":"official","src":[0,1,2]},{"name":"Phone Interview","what":"Phỏng vấn qua điện thoại (theo tin LEAD GEN 2026).","tips":["Chuẩn bị câu trả lời ngắn gọn cho 'Why P&G / Why track này' và 2–3 câu chuyện STAR.","Nghe điện thoại ở nơi yên tĩnh, có sẵn CV trước mặt."],"basis":"official","src":[3]},{"name":"3 rounds of interview with C-levels","what":"Tin LEAD GEN 2026 ghi 3 vòng phỏng vấn với lãnh đạo cấp cao. Theo trang hiring process toàn cầu, phỏng vấn giúp P&G hiểu ứng viên và để ứng viên đặt câu hỏi; có thể có thêm bước tuỳ vị trí. Ứng viên và các trang luyện thi báo cáo phỏng vấn chủ yếu là câu hỏi hành vi về kinh nghiệm quá khứ.","tips":["Gắn mỗi câu chuyện STAR với một hành vi cụ thể: lãnh đạo, chủ động nhận trách nhiệm (ownership), sáng tạo, thực thi đến cùng.","Nêu rõ vai trò của bạn ('tôi' chứ không chỉ 'chúng tôi') và kết quả bằng số.","Chuẩn bị câu hỏi ngược sâu về ngành hàng/brand P&G ở Việt Nam."],"basis":"official","src":[3,2,9]}],"tests":[{"name":"PEAK Performance Assessment","provider":null,"format":"Theo P&G: đánh giá nền tảng, kinh nghiệm, sở thích và thái độ làm việc, đo mức phù hợp với năng lực P&G; đa số ứng viên mất khoảng 20 phút; link gửi qua email. Gồm 4 phần; nộp xong phần nào thì không quay lại sửa được; phải tự làm, không dùng trợ giúp hay AI (official). Các trang luyện thi mô tả đây là bài trắc nghiệm tính cách kết hợp tình huống (SJT) (reported).","basis":"official","src":[1,0,8]},{"name":"Interactive Assessment (IA)","provider":"Aon (cut-e), theo các trang luyện thi, P&G không công bố","format":"Theo P&G: khoảng 30 phút, hơn 20 ngôn ngữ, gồm chuỗi bài đánh giá năng lực nhận thức ngắn, giao tuỳ vị trí. Các trang luyện thi mô tả 3 game Switch Challenge, Digit Challenge, Grid Challenge (suy luận suy diễn, số học, trí nhớ không gian), có giới hạn thời gian và không quay lại câu trước được (reported).","basis":"official","src":[0,8]}],"values":{"name":"P&G Purpose, Values and Principles (PVP)","items":["Integrity","Leadership","Ownership","Passion for Winning","Trust","Ghi chú: 'Success Drivers' / 'PEAK Performance Factors' chỉ xuất hiện trên các trang luyện thi, chưa có thông tin công khai đáng tin cậy từ P&G về danh sách chính thức."],"basis":"official","src":[7]},"prep":["Theo dõi pgcareers.com và kênh tuyển dụng của trường từ tháng 9; LEAD GEN có thể chia nhiều đợt (batch) và xét cuốn chiếu nên nộp sớm.","Study guide: đọc phần PEAK (tính cách + tình huống) và Interactive Assessment (game nhận thức) để biết mỗi bài đo gì.","Mental math gym hằng ngày: game kiểu Digit Challenge cần tính nhẩm nhanh và chính xác.","Luyện chủ đề Logical (quy luật, suy luận suy diễn) có bấm giờ để chuẩn bị cho dạng Switch Challenge.","Luyện chủ đề SJT, đối chiếu lựa chọn với 5 giá trị PVP (Integrity, Leadership, Ownership, Passion for Winning, Trust).","Làm Mock test 'P&G-style' ở chế độ không quay lại câu trước, đúng giới hạn thời gian; nhớ rằng trượt bài thật phải chờ 12 tháng.","Viết 6–8 câu chuyện STAR bằng tiếng Anh cho phỏng vấn điện thoại và 3 vòng với C-level; tập nói kết quả bằng số."],"mock":{"title":"P&G-style practice test","topics":{"Quant":6,"Logical":6,"Verbal":0,"DI":2,"SJT":6},"minutes":20,"navigation":false,"note":"Cấu hình luyện tập do app thiết kế (không phải bài test thật của P&G). Chế độ không quay lại câu trước mô phỏng một phần quy tắc chính thức của PEAK: bài có 4 phần và không quay lại được một phần sau khi đã nộp (P&G không công bố giới hạn thời gian). Phần Interactive Assessment thật là các bài nhận thức ngắn dạng tương tác, app chỉ luyện được tư duy số và logic tương đương.","basis":"general","src":[1,0,8]},"pitfalls":["Nộp muộn: LEAD GEN xét cuốn chiếu theo đợt; cộng đồng báo cáo một số track đã đủ người trước hạn (reported).","Trả lời PEAK theo kiểu 'hình mẫu lý tưởng' thiếu nhất quán thay vì trung thực (general).","Ở game IA, cố chính xác tuyệt đối mà mất tốc độ, hoặc ngược lại; các trang luyện thi báo cáo không quay lại câu trước được (reported).","Câu chuyện STAR dùng 'chúng tôi' và không nêu kết quả đo được (general).","Bỏ sót email mời làm bài đánh giá, vì kết quả và link đều gửi qua email (official).","Làm bài đánh giá khi chưa sẵn sàng: nếu không đạt phải chờ 12 tháng mới được làm lại, và với đa số vị trí kết quả tự động quyết định việc đi tiếp (official)."],"sources":[{"title":"Assessment Overview at P&G","url":"https://pgcareers.com/assessment-overviews","publisher":"P&G Careers","year":"2025","accessed":"2026-11-13"},{"title":"Peak Performance Assessment Overview","url":"https://www.pgcareers.com/eu/en/peak-performance-assessment","publisher":"P&G Careers","year":"2026","accessed":"2026-11-13"},{"title":"How do we hire?","url":"https://pgcareers.com/hiring-process","publisher":"P&G Careers","year":"2026","accessed":"2026-11-13"},{"title":"[Bình Dương-HCM] Chương trình tuyển dụng thực tập sinh P&G Lead Gen 2026","url":"https://ybox.vn/tuyen-dung/binh-duong-hcm-chuong-trinh-tuyen-dung-thuc-tap-sinh-p-and-g-lead-gen-2026-tu-tap-doan-hang-tieu-dung-da-quoc-gia-procter-and-gamble-muc-luong-12-17-trieu-thang-68ff7425c7b0e427d28e9b2c","publisher":"YBOX","year":"2025","accessed":"2026-11-13"},{"title":"P&G LEAD GEN 2026 (403 khi kiểm tra 2026-11-13)","url":"https://careerportal.vinuni.edu.vn/job/pg-lead-gen-2026-12217","publisher":"VinUni Career Portal","year":"2025","accessed":"2026-11-13"},{"title":"P&G LEAD GEN 2027 (vn-student-programs, cộng đồng; ghi hạn Batch 2 31/10/2026)","url":"https://github.com/techjobs-vn/vn-student-programs/pull/30","publisher":"GitHub (cộng đồng)","year":"2026","accessed":"2026-11-13"},{"title":"P&G LEAD GEN Sales Intern Full-time 2026","url":"https://vn.joboko.com/viec-lam-hcm-tap-doan-hang-tieu-dung-da-quoc-gia-procter-gamble-p-g-tuyen-dung-p-g-lead-gen-sales-intern-full-time-2026-xvi6293798","publisher":"Joboko","year":"2025","accessed":"2026-11-13"},{"title":"Purpose, Values and Principles","url":"https://us.pg.com/policies-and-practices/purpose-values-and-principles/","publisher":"Procter & Gamble","year":"2025","accessed":"2026-11-13"},{"title":"P&G Online Assessment Test guide (third-party prep)","url":"https://www.jobtestprep.com/procter-and-gamble-assessment","publisher":"JobTestPrep","year":"2026","accessed":"2026-11-13"},{"title":"Procter & Gamble Interview Questions in Vietnam (candidate-reported)","url":"https://www.glassdoor.com/Interview/Procter-and-Gamble-Vietnam-Interview-Questions-EI_IE544.0,18_IL.19,26_IN251.htm","publisher":"Glassdoor","year":"n/a","accessed":"2026-11-13"}]},{"id":"unilever","name":"Unilever Vietnam","program":"Unilever Future Leaders Programme (UFLP)","industry":"FMCG","lastChecked":"2026-11-13","summary":"UFLP là chương trình Management Trainee (quản trị viên tập sự) thường niên của Unilever Việt Nam, dành cho sinh viên quốc tịch Việt Nam sắp/mới tốt nghiệp (tối đa 2 năm kinh nghiệm). Các đợt UFLP 2025 và 2026 tại Việt Nam đều có 3 vòng: Online Application & Aptitude Test → Digital Interview → Discovery Center. Điểm khác biệt: không có vòng phỏng vấn trực tiếp đầu tiên; thay vào đó là bài đánh giá online (ở UFLP UK & Ireland: portrait personality test + online assessment) và Digital Interview quay sẵn, cuối cùng là Discovery Centre mô phỏng 'một ngày làm Future Leader'.","intake":{"text":"UFLP 2026: hạn nộp 23:59 ngày 29/12/2025; Digital Interview tháng 1–2/2026, Discovery Center tháng 3/2026, bắt đầu làm việc tháng 4/2026. UFLP 2025: hạn 23:59 ngày 26/01/2025, Digital Interview tháng 2–3/2025, Discovery Center tháng 3–4/2025, bắt đầu tháng 4/2025. Lịch này do Unilever công bố, nhưng tin gốc trên careers.unilever.com đã gỡ; nguồn còn truy cập được là bản đăng lại trên YBOX và cổng việc làm NEU. UFLP 2027: chưa tìm thấy tin chính thức trên careers.unilever.com (kiểm tra 13/11/2026); chỉ có một bài đăng cá nhân trên LinkedIn (chưa xác minh) nói hạn 30/11/2026. Các năm gần đây đơn mở khoảng tháng 11 đến tháng 1.","basis":"reported","src":[2,6,0,5]},"eligibility":[{"text":"Quốc tịch Việt Nam, tốt nghiệp Cử nhân/Thạc sĩ, tối đa 2 năm kinh nghiệm làm việc chính thức. Năm tốt nghiệp: tin chính thức UFLP 2026 (nay đã gỡ) ghi tốt nghiệp năm 2026 hoặc 2027; bản đăng lại trên YBOX ghi tốt nghiệp trong năm 2026.","basis":"official","src":[1,2]},{"text":"UFLP 2026: GPA từ 7.0/10.0 hoặc tương đương; kinh nghiệm lãnh đạo ở CLB, tổ chức, hoạt động xã hội là lợi thế.","basis":"official","src":[2,1]},{"text":"Theo tin chính thức UFLP 2026 (nay đã gỡ): chỉ đơn nộp qua link/cổng chính thức của Unilever mới hợp lệ; đơn nộp qua nền tảng khác không được xét.","basis":"official","src":[1]},{"text":"Yêu cầu tiếng Anh cụ thể (IELTS/TOEIC): Chưa có thông tin công khai đáng tin cậy. Tuy vậy các vòng Digital Interview và Discovery Centre của UFLP toàn cầu diễn ra bằng tiếng Anh nên cần tiếng Anh giao tiếp tốt.","basis":"general","src":[3]}],"functions":[{"text":"UFLP 2026 Việt Nam tuyển 7 mảng: Marketing, Customer Development (Sales), Supply Chain – Manufacturing, Supply Chain – Non-Manufacturing, Unilever Food Solutions (Go To Market), Finance, Human Resources. (UFLP 2025 tuyển 6 phòng ban.)","basis":"official","src":[2,6]},{"text":"Ở UFLP UK & Ireland, ứng viên chỉ được chọn một function trong một đơn ứng tuyển.","basis":"official","src":[3]}],"stages":[{"name":"Online Application & Aptitude Test (Vòng 1)","what":"Điền đơn trực tuyến và làm bài đánh giá sơ bộ (Aptitude Test). Tin tuyển Việt Nam chỉ ghi 'Aptitude Test', không nêu định dạng hay nhà cung cấp. Ở UFLP UK & Ireland, 'profile assessment' gồm 2 giai đoạn: bài trắc nghiệm tính cách (portrait personality test) và một bài đánh giá online, đo đặc điểm nhận thức, cảm xúc và xã hội; có phản hồi cá nhân sau mỗi giai đoạn. Các trang luyện thi (không chính thức) mô tả dạng game với số lượng khác nhau (5, 11 hoặc 12 game).","tips":["Làm trong môi trường yên tĩnh, máy tính ổn định, một lần ngồi liền.","Bài tính cách: trả lời trung thực, nhất quán; cố 'đoán ý' thường tạo hồ sơ mâu thuẫn.","Luyện Mental math gym và chủ đề Logical để tăng tốc độ xử lý cho phần đánh giá nhận thức.","Chọn function kỹ trước khi nộp vì chỉ được chọn một (UFLP UK & Ireland)."],"basis":"official","src":[2,6,3]},{"name":"Digital Interview (Vòng 2)","what":"Phỏng vấn video quay sẵn, làm bất cứ lúc nào trong hạn (UFLP 2026 Việt Nam: tháng 1–2/2026). Trang UFLP UK & Ireland mô tả Digital Interview gồm 3 câu hỏi ngắn, sau đó là một business case dùng tình huống của Unilever; bài nộp được người thật xem xét (Unilever nói không dùng AI để sàng lọc). Reported: ứng viên trên Glassdoor báo cáo mỗi câu có giới hạn thời gian và chỉ được quay một lần; báo cáo của các ứng viên khác nhau không thống nhất (có người nói được quay 2 lần).","tips":["Chuẩn bị 5–6 câu chuyện theo STAR về lãnh đạo, vượt khó, làm việc nhóm, tạo tác động.","Tìm hiểu các brand của Unilever Việt Nam và tin tức công ty, vì TargetJobs nhận xét Unilever cố ý ít tiết lộ nội dung câu hỏi.","Tập trả lời trước camera có bấm giờ (khoảng 1–2 phút/câu), nhìn vào ống kính, nói tiếng Anh rõ ràng.","Với business case: nêu cấu trúc (vấn đề → phân tích → đề xuất → tác động) trong thời gian ngắn."],"basis":"official","src":[2,3,4,8]},{"name":"Discovery Center (Vòng 3)","what":"Vòng cuối kiểu assessment centre (UFLP 2026 Việt Nam: tháng 3/2026). Theo trang UFLP UK & Ireland: ứng viên được mời trải nghiệm 'một ngày làm Future Leader', là một ngày trực tiếp gồm họp dự án, thử thách kinh doanh, họp nhóm với nhân viên Unilever và một buổi phỏng vấn. Định dạng cụ thể tại Việt Nam: Chưa có thông tin công khai đáng tin cậy.","tips":["Luyện case nhóm: lắng nghe, xây trên ý người khác, giữ thời gian, tổng kết; vai trò không quan trọng bằng chất lượng đóng góp.","Luyện đọc nhanh số liệu kinh doanh (DI) để ra quyết định dựa trên dữ liệu khi thuyết trình.","Chuẩn bị câu trả lời 'Why Unilever / Why function này' gắn với purpose và brand cụ thể."],"basis":"official","src":[2,3]},{"name":"UFLP 2027 (reported – chưa xác minh)","what":"Chưa tìm thấy tin UFLP 2027 Việt Nam trên careers.unilever.com (kiểm tra 13/11/2026). Một bài đăng cá nhân trên LinkedIn của một nhân viên Unilever nói đơn đã mở, hạn 30/11/2026, và liệt kê 4 bước: CV application, psychometric assessments, group case interview, Discovery Center. Thông tin này khác cấu trúc 2025–2026 và chưa được xác minh, nên không dùng làm căn cứ chính.","tips":["Kiểm tra fanpage Unilever Careers Vietnam và careers.unilever.com xem UFLP 2027 đã mở chưa; chưa có tin chính thức xác nhận hạn nộp hay quy trình."],"basis":"reported","src":[5]}],"tests":[{"name":"Profile assessment (2 giai đoạn)","provider":null,"format":"UFLP UK & Ireland: 2 giai đoạn, gồm portrait personality test và online assessment, đo đặc điểm nhận thức, cảm xúc, xã hội; có phản hồi cá nhân sau mỗi giai đoạn. Các trang luyện thi (không chính thức) mô tả dạng game với số lượng khác nhau (5, 11 hoặc 12 game). Tin tuyển Việt Nam 2026 chỉ gọi là 'Aptitude Test'. Nhà cung cấp: Chưa có thông tin công khai đáng tin cậy.","basis":"official","src":[3,2]},{"name":"Lịch sử: game Pymetrics + video HireVue","provider":"Pymetrics, HireVue (theo báo chí năm 2017)","format":"Business Insider (2017) đưa tin Unilever bỏ CV ở vòng đầu, cho ứng viên chơi khoảng 12 game của Pymetrics rồi phỏng vấn video HireVue. Đây là thông tin lịch sử, không xác nhận cho UFLP Việt Nam hiện nay.","basis":"reported","src":[7]},{"name":"Digital Interview","provider":null,"format":"Official (UFLP UK & Ireland): 3 câu hỏi ngắn và một business case dùng tình huống Unilever; người thật xem xét bài nộp. Reported: giới hạn thời gian mỗi câu; số lần quay được báo cáo không thống nhất (1 hoặc 2 lần).","basis":"official","src":[3,8]}],"values":{"name":"Unilever Standards of Leadership","items":["Chưa có thông tin công khai đáng tin cậy về danh sách đầy đủ hiện hành; TargetJobs khuyên ứng viên UFLP đọc về leadership standards của Unilever trước Digital Interview, nên hãy tìm bản mới nhất trên trang chính thức của Unilever."],"basis":"general","src":[4]},"prep":["Kiểm tra fanpage Unilever Careers Vietnam và careers.unilever.com xem UFLP 2027 đã mở chưa; chưa có tin chính thức xác nhận hạn nộp (một bài đăng cá nhân trên LinkedIn nói 30/11/2026, chưa xác minh). Chọn đúng một function.","Study guide: đọc phần bài đánh giá tính cách và bài đánh giá nhận thức online để hiểu mỗi phần đo gì; làm bài khi tỉnh táo, liền một lần.","Mental math gym 10 phút/ngày để tăng tốc độ tính nhẩm và phản xạ, hỗ trợ cả game lẫn phần số liệu ở Discovery Centre.","Luyện chủ đề Logical và DI (biểu đồ doanh số, thị phần FMCG) vì Discovery Centre và business case dùng nhiều số liệu.","Luyện chủ đề SJT để làm quen tư duy ra quyết định trong tình huống công việc.","Viết 5–6 câu chuyện STAR bằng tiếng Anh và tập quay video có bấm giờ cho Digital Interview (3 câu hỏi ngắn + business case).","Làm Mock test 'Unilever-style' có bấm giờ, không quay lại câu trước, để quen áp lực thời gian.","Đọc về các brand Unilever ở Việt Nam và chuẩn bị ý tưởng cho group case."],"mock":{"title":"Unilever-style practice test","topics":{"Quant":4,"Logical":6,"Verbal":2,"DI":4,"SJT":4},"minutes":20,"navigation":false,"note":"Vòng 1 thật là 'Aptitude Test' (ở UFLP UK & Ireland: portrait personality test + online assessment đo nhận thức, cảm xúc, xã hội). App không chấm được bài tính cách hay phần đo đặc điểm cảm xúc–xã hội, và không mô phỏng được giao diện game (nếu có, theo trang luyện thi), chỉ luyện được nền tảng nhận thức (logic, tính nhẩm, đọc số liệu) và SJT. Tắt quay lại câu trước để luyện áp lực thời gian; chưa có nguồn chính thức về điều hướng. Digital Interview và Discovery Centre cần luyện riêng bằng video và case nhóm.","basis":"general","src":[2,3]},"pitfalls":["Nộp đơn qua trang tổng hợp hoặc nền tảng khác thay vì link chính thức: đơn không được xét (official).","Trả lời bài tính cách theo kiểu 'hình mẫu lý tưởng' thay vì trung thực, dẫn đến hồ sơ thiếu nhất quán (general).","Lần đầu quay Digital Interview mà không tập trước: ứng viên báo cáo mỗi câu có giới hạn thời gian và số lần quay hạn chế (reported).","Trả lời chung chung 'Why Unilever' mà không nêu brand hay sáng kiến cụ thể ở Việt Nam (general).","Ở case nhóm Discovery Centre, nói nhiều nhưng không dựa trên số liệu, hoặc lấn át người khác (general)."],"sources":[{"title":"Unilever Future Leaders' Programme 2026 - Marketing (Ho Chi Minh City) (tin đã gỡ, 404 khi kiểm tra 2026-11-13)","url":"https://careers.unilever.com/en/job/ho-chi-minh-city/unilever-future-leaders-programme-2026-marketing/34155/88566721056","publisher":"Unilever Careers","year":"2025","accessed":"2026-11-13"},{"title":"Unilever Future Leaders' Programme 2026 - Supply Chain (Manufacturing) (Ho Chi Minh City) (tin đã gỡ, 404 khi kiểm tra 2026-11-13)","url":"https://careers.unilever.com/job/ho-chi-minh-city/unilever-future-leaders-programme-2026-supply-chain-manufacturing/34155/88566721008","publisher":"Unilever Careers","year":"2025","accessed":"2026-11-13"},{"title":"[Toàn Quốc] Unilever Future Leaders Programme 2026 - Chương trình tuyển dụng Quản trị viên tập sự","url":"https://ybox.vn/tuyen-dung/toan-quoc-unilever-future-leaders-programme-2026-chuong-trinh-tuyen-dung-quan-tri-vien-tap-su-tai-tap-doan-da-quoc-gia-unilever-marketing-customer-development-supply-chain-unilever-foods-solution-finance-human-resources-690de36fe48b1a70799fde9d","publisher":"YBOX","year":"2025","accessed":"2026-11-13"},{"title":"UK and Ireland Unilever Future Leaders Programme 2026","url":"https://careers.unilever.com/uk-and-ireland-unilever-future-leaders-programme-2026","publisher":"Unilever Careers","year":"2026","accessed":"2026-11-13"},{"title":"Applying to Unilever's Future Leaders Programme: the digital interview","url":"https://targetjobs.co.uk/employers/unilever/applying-to-unilevers-future-leaders-programme-the-digital-interview-453149","publisher":"TargetJobs","year":"2025","accessed":"2026-11-13"},{"title":"Bài đăng cá nhân trên LinkedIn về UFLP 2027 (nhân viên Unilever chia sẻ; chưa xác minh)","url":"https://www.linkedin.com/in/hongphuongvo/","publisher":"LinkedIn (cá nhân)","year":"2026","accessed":"2026-11-13"},{"title":"Quản trị viên tập sự Unilever Future Leaders Programme (UFLP) - Unilever Việt Nam","url":"https://jobs.neu.edu.vn/jobs/quan-tri-vien-tap-su-unilever-future-leaders-programme-uflp-unilever-viet-nam-1202412191518","publisher":"Trung tâm Đổi mới sáng tạo và Hướng nghiệp ĐH Kinh tế Quốc dân","year":"2024","accessed":"2026-11-13"},{"title":"Consumer goods giant Unilever has been hiring employees using brain games and artificial intelligence","url":"https://www.businessinsider.in/consumer-goods-giant-unilever-has-been-hiring-employees-using-brain-games-and-artificial-intelligence-and-its-a-huge-success/articleshow/59356757.cms","publisher":"Business Insider","year":"2017","accessed":"2026-11-13"},{"title":"Unilever Interview review (candidate-reported)","url":"https://www.glassdoor.co.uk/Interview/Unilever-Interview-E3513-RVW90689487.htm","publisher":"Glassdoor","year":"n/a","accessed":"2026-11-13"}]},{"id":"heineken","name":"HEINEKEN Vietnam","program":"HEINEKEN Vietnam NextGen (Management Trainee Program)","industry":"FMCG (Bia & đồ uống)","lastChecked":"2026-11-13","summary":"NextGen là chương trình Management Trainee của HEINEKEN Vietnam dành cho sinh viên mới tốt nghiệp hoặc dưới 2 năm kinh nghiệm, kéo dài 18 tháng luân chuyển qua các phòng ban. Mỗi năm công ty mở theo từng khối với lịch riêng: Supply Chain (2025, 2027) và Commerce/Sales & Marketing (2026). Quy trình gồm nộp hồ sơ, đánh giá năng lực trực tuyến (năm 2025 là Gamified Online Assessment), phỏng vấn sơ bộ, đánh giá toàn diện (Assessment Centre, ít nhất đến 2024 gọi là 'Brew Day') và, ở một số khối, một vòng phỏng vấn cuối.","intake":{"text":"Mỗi khối mở theo lịch riêng. NextGen 2025 (Supply Chain): nộp đơn 14/02–30/03/2025, đi làm từ 06/2025. NextGen Commerce 2026 (Sales & Marketing): nộp đơn 05/05–16/06/2026, thư mời nhận việc tháng 8, bắt đầu tháng 09/2026. NextGen 2027 – Supply Chain: nộp đơn 12/10–20/11/2026 (đang mở tại ngày 13/11/2026), đi làm từ 03/2027.","basis":"official","src":[0,1,2,3]},"eligibility":[{"text":"Khối Supply Chain (2025, 2027): tốt nghiệp Cử nhân/Thạc sĩ ngành liên quan, GPA ≥ 7.0/10 (2.8/4.0); mới tốt nghiệp hoặc dưới 2 năm kinh nghiệm; giao tiếp tốt bằng tiếng Anh; sẵn sàng di chuyển và công tác tại các nhà máy HEINEKEN Việt Nam.","basis":"official","src":[1,3]},{"text":"Khối Commerce 2026: tốt nghiệp ngành Kinh doanh, Marketing, Truyền thông hoặc liên quan, GPA ≥ 7.0/10 (2.8/4.0); mới tốt nghiệp hoặc dưới 2 năm kinh nghiệm (ưu tiên FMCG, đồ uống, hàng tiêu dùng); sử dụng tốt tiếng Việt và tiếng Anh; có tiềm năng lãnh đạo thể hiện qua hoạt động ngoại khóa, dự án hoặc kinh nghiệm làm việc.","basis":"official","src":[2]}],"functions":[{"text":"Supply Chain 2025: Technology & Brewing, Engineering & Packaging, Customer Service, Logistics & Planning (CSLP); 18 tháng luân chuyển qua các phòng ban trong chuỗi cung ứng. NextGen 2027 – Supply Chain cũng là 18 tháng luân chuyển.","basis":"official","src":[1,3]},{"text":"Commerce 2026 (tuyển cả Sales và Marketing): hành trình 18 tháng luân chuyển qua các bộ phận với dự án thực tế, mô hình đào tạo 10-20-70; hoàn thành tốt có cơ hội nhận vị trí quản lý.","basis":"official","src":[2]},{"text":"HEINEKEN Vietnam còn có HEINEKEN Global Graduate Program, một chương trình khác: 3 năm, 3 vòng luân chuyển 6 tháng (Supply Chain hoặc People), sau đó 18 tháng làm việc tại Việt Nam.","basis":"official","src":[4,5]}],"stages":[{"name":"Online application","what":"Nộp hồ sơ online trong cửa sổ khoảng 6 tuần (2025: 14/02–30/03/2025; Commerce 2026: 05/05–16/06/2026; Supply Chain 2027: 12/10–20/11/2026).","tips":["Chọn đúng khối (Supply Chain hay Commerce), vì mỗi khối có lịch và tiêu chí riêng.","Nộp sớm: ở các khối 2026 và 2027, vòng đánh giá online diễn ra song song với thời gian nhận hồ sơ."],"basis":"official","src":[0,1,2,3]},{"name":"Online assessment","what":"2025: Gamified Online Assessment (tháng 02–03/2025). Commerce 2026: đánh giá năng lực trực tuyến tháng 5–6/2026. Supply Chain 2027: đánh giá năng lực trực tuyến tháng 10–11/2026. Các tin tuyển dụng không mô tả định dạng chi tiết.","tips":["Luyện các bài reasoning ngắn có bấm giờ để quen áp lực tốc độ (general).","Nếu là bài gamified, giữ tập trung và làm theo hướng dẫn từng game; đừng cố đoán 'đáp án đúng' về tính cách (general)."],"basis":"official","src":[1,2,3]},{"name":"Initial / Preliminary interview","what":"Phỏng vấn sơ bộ (2025: tháng 3–4; Commerce 2026: tháng 6; Supply Chain 2027: tháng 11/2026).","tips":["Chuẩn bị 3–4 câu chuyện theo STAR, gắn với ba trụ cột HEINEKEN Vietnam nêu trên trang tuyển dụng: Pioneer, Grow, Together.","Chuẩn bị lý do chọn khối. Với Supply Chain, nói rõ bạn sẵn sàng làm việc tại nhà máy."],"basis":"official","src":[1,2,3,4]},{"name":"Assessment Centre (Đánh giá toàn diện / Brew Day)","what":"2025: Assessment Center tháng 04/2025. Commerce 2026: đánh giá toàn diện tháng 7/2026. Supply Chain 2027: đánh giá toàn diện tháng 12/2026. Tin tuyển dụng không mô tả các hoạt động cụ thể. Ít nhất đến đợt 2024, vòng này được gọi là 'Brew Day (Assessment Center)'.","tips":["Luyện giải case kinh doanh hoặc vận hành trong 30–60 phút và trình bày ngắn gọn (general).","Trong hoạt động nhóm: đóng góp có cấu trúc, lắng nghe, tổng kết; tránh lấn át người khác (general)."],"basis":"official","src":[1,2,3,6,8]},{"name":"Final / In-depth interview","what":"Phỏng vấn cuối hoặc phỏng vấn chuyên sâu (2025: tháng 5/2025; Commerce 2026: tháng 7/2026). Tin NextGen 2027 – Supply Chain chỉ nêu 4 vòng, kết thúc ở vòng đánh giá toàn diện tháng 12/2026.","tips":["Ôn lại hiểu biết về thị trường bia Việt Nam và các thương hiệu của công ty (Heineken, Tiger, Larue, Bia Việt, Strongbow, ...).","Chuẩn bị câu hỏi cho lãnh đạo về lộ trình 18 tháng."],"basis":"official","src":[1,2,3]}],"tests":[{"name":"Gamified Online Assessment (NextGen 2025)","provider":null,"format":"Bài đánh giá online dạng game hoá. Tin tuyển dụng không nêu nhà cung cấp, số phần hay thời gian.","basis":"official","src":[1]},{"name":"Online assessment (NextGen Commerce 2026 / Supply Chain 2027)","provider":null,"format":"'Đánh giá năng lực trực tuyến'. Tin tuyển dụng không mô tả định dạng.","basis":"official","src":[2,3]},{"name":"Nền tảng Pulsifi (theo case study của vendor)","provider":"Pulsifi (theo case study công khai của Pulsifi về NextGen Supply Chain và trang ứng tuyển HVNG 2024; không xác nhận cho chu kỳ hiện tại)","format":"Case study của vendor nói HEINEKEN Vietnam dùng nền tảng Pulsifi (predictive analytics, video assessment) cho NextGen Supply Chain. Đây không phải lời công ty tự công bố.","basis":"reported","src":[6,7]},{"name":"Online assessment của HEINEKEN Global Graduate Program 2025 (chương trình khác, chỉ để tham khảo)","provider":null,"format":"Tình huống hành vi (situational behaviour scenarios, 'không cần chuẩn bị trước') kèm một bài cognitive test. Chưa xác nhận NextGen dùng cùng định dạng.","basis":"official","src":[5]}],"values":{"name":"HEINEKEN Vietnam – Why join us (trang tuyển dụng chính thức)","items":["Pioneer (courage to lead, challenge boundaries, drive innovation)","Grow","Together (The Joy of True Togetherness; care, safety, respect)"],"basis":"official","src":[4]},"prep":["Xác định khối đang mở (tại 13/11/2026: NextGen 2027 – Supply Chain, hạn 20/11/2026) và nộp sớm vì vòng online chạy song song.","Study guide: đọc phần Logical và Situational Judgement để làm quen các bài đánh giá ngắn có bấm giờ (định dạng thật chưa được công bố).","Mental math gym: 10 phút/ngày để tăng tốc tính nhẩm phần trăm, tỷ lệ; hữu ích cho cả test lẫn case vận hành hoặc sales.","Luyện chủ đề DI (đọc bảng/biểu đồ) để chuẩn bị cho case Supply Chain hoặc Commerce dựa trên số liệu.","Làm Mock test 'HEINEKEN-style' 2–3 lần, xem lại câu sai theo từng chủ đề.","Chuẩn bị câu chuyện STAR gắn với Pioneer, Grow, Together của HEINEKEN Vietnam.","Luyện case nhóm 45 phút với bạn bè: phân vai, quản lý thời gian, trình bày trong 5 phút."],"mock":{"title":"HEINEKEN-style practice test","topics":{"Quant":4,"Logical":6,"Verbal":0,"DI":4,"SJT":6},"minutes":20,"navigation":true,"note":"Năm 2025 bài thật là Gamified Online Assessment; các năm 2026–2027 chỉ ghi 'đánh giá năng lực trực tuyến' mà không mô tả định dạng. App không mô phỏng được game, chỉ luyện năng lực nền (logic, số liệu, phán đoán tình huống) dưới áp lực thời gian. Tỷ trọng là ước lượng chung, không phải cấu trúc bài thật.","basis":"general","src":[1,2,3]},"pitfalls":["Nhầm khối hoặc lịch: mỗi khối NextGen có thời gian và số vòng khác nhau (2027 Supply Chain có 4 vòng, Commerce 2026 có 5 vòng).","Nộp muộn trong khi vòng đánh giá online đã bắt đầu song song.","Không sẵn sàng làm việc tại nhà máy/tỉnh dù đây là yêu cầu nêu rõ của khối Supply Chain.","Nhầm NextGen với HEINEKEN Global Graduate Program (khác thời lượng, có luân chuyển quốc tế, quy trình riêng).","Ở Assessment Centre: chỉ tập trung vào đáp án mà bỏ qua cách phối hợp nhóm (general)."],"sources":[{"title":"[Toàn Quốc] HEINEKEN Vietnam NextGen 2025 - Management Trainee Program","url":"https://vietnamworks.com/toan-quoc-heineken-vietnam-nextgen-2025-management-trainee-program-1869861-jv","publisher":"VietnamWorks","year":"2025","accessed":"2026-11-13"},{"title":"Heineken Việt Nam tuyển dụng Quản Trị Viên Tập Sự HEINEKEN Vietnam NextGen 2025 (Technology & Brewing, Engineering & Packaging, CSLP)","url":"https://ybox.vn/tuyen-dung/toan-quoc-heineken-viet-nam-tuyen-dung-chuong-trinh-quan-tri-vien-tap-su-heineken-vietnam-nextgen-2025-danh-cho-sinh-vien-moi-tot-nghiep-hoac-duoi-2-nam-kinh-nghiem-technology-and-brewing-engineering-and-packaging-customer-service-logistics-and-planning-67b2ee6ba12a102e71232d8c","publisher":"YBOX","year":"2025","accessed":"2026-11-13"},{"title":"Heineken Việt Nam - Chương Trình Quản Trị Viên Tập Sự NextGen Commerce 2026 (Sales & Marketing)","url":"https://ybox.vn/tuyen-dung/toan-quoc-heineken-viet-nam-chuong-trinh-quan-tri-vien-tap-su-nextgen-commerce-2026-danh-cho-sinh-vien-moi-tot-nghiep-hoac-duoi-2-nam-kinh-nghiem-sales-and-marketing-69f80755582ea202f2e83ba7","publisher":"YBOX","year":"2026","accessed":"2026-11-13"},{"title":"Chương Trình Quản Trị Viên Tập Sự NextGen 2027 - Supply Chain Tại Công Ty Bia Heineken Việt Nam","url":"https://ybox.vn/tuyen-dung/toan-quoc-chuong-trinh-quan-tri-vien-tap-su-nextgen-2027-supply-chain-tai-cong-ty-bia-heineken-viet-nam-danh-cho-sinh-vien-moi-tot-nghiep-hoac-duoi-2-nam-kinh-nghiem-6acd483e1a62196a64a068b0","publisher":"YBOX","year":"2026","accessed":"2026-11-13"},{"title":"Careers at HEINEKEN Vietnam","url":"https://careers.theheinekencompany.com/English/HEINEKEN-Vietnam","publisher":"HEINEKEN Careers","year":"2026","accessed":"2026-11-13"},{"title":"Chương trình tuyển dụng nhân sự toàn cầu sau đại học 2025 - HEINEKEN Vietnam (Global Graduate Program)","url":"https://jobs.neu.edu.vn/jobs/chuong-trinh-tuyen-dung-nhan-su-toan-cau-sau-dai-hoc-2025-heineken-vietnam-1202509101453","publisher":"Trung tâm Đổi mới sáng tạo và Hướng nghiệp – ĐH Kinh tế Quốc dân","year":"2025","accessed":"2026-11-13"},{"title":"HEINEKEN Vietnam Next Gen (HVNG) 2024","url":"https://job.pulsifi.me/companies/heineken-vietnam/8ee0f7b2-4456-4eda-bd90-5ca8c3f0be1d/heineken-vietnam-next-gen-hvng-2024","publisher":"Pulsifi (trang ứng tuyển)","year":"2024","accessed":"2026-11-13"},{"title":"Empowering HEINEKEN Vietnam with predictive analytics and video assessment to recruit top young talents","url":"https://www.casestudies.com/company/pulsifi/case-study/empowering-heineken-vietnam-with-predictive-analytics-and-video-assessment-to-recruit-top-young-talents","publisher":"Pulsifi (case study của vendor)","year":"không ghi","accessed":"2026-11-13"},{"title":"Chương Trình Tuyển Dụng Quản Trị Viên Tập Sự HEINEKEN Vietnam NextGen 2023","url":"https://enijobs.vn/heineken-vietnam-nextgen-2023/","publisher":"EniJobs","year":"2023","accessed":"2026-11-13"}]},{"id":"suntory-pepsico","name":"Suntory PepsiCo Vietnam","program":"Suntory PepsiCo Management Trainee (MT)","industry":"FMCG (Nước giải khát)","lastChecked":"2026-11-13","summary":"Chương trình Management Trainee của Suntory PepsiCo Việt Nam dành cho sinh viên mới tốt nghiệp hoặc tối đa 2 năm kinh nghiệm, với mục tiêu lên vị trí quản lý trong 3 năm. Quy trình MT2026 gồm Application, Testing (một bài aptitude test bằng tiếng Anh, chỉ làm một lần qua link email), Initial Interview và Career Camp. Career Camp gồm Business Case và Panel Interview, tiến hành bằng cả tiếng Việt và tiếng Anh.","intake":{"text":"Hạn nộp MT2026 là 31/12/2025, onboard 03/2026. Ứng viên nộp trước 07/12/2025 được nhận một bài aptitude test mẫu. Ngày mở đơn 25/11/2025 chỉ có trên tin đăng lại, chưa kiểm chứng trên nguồn chính thức. MT2025: onboard 04/2025; ai nộp trước 30/11/2024 được làm thử bài aptitude. Tại ngày 13/11/2026, trang tuyển dụng chưa có MT2027.","basis":"official","src":[0,1,2,3,4]},"eligibility":[{"text":"MT2026: mới tốt nghiệp Cử nhân/Thạc sĩ (mọi ngành) hoặc tối đa 2 năm kinh nghiệm toàn thời gian; quốc tịch Việt Nam; GPA trên 7.0/10 hoặc tương đương; đi làm toàn thời gian từ 03/2026. Có thêm một diện riêng cho nhân viên nội bộ (L4/L5).","basis":"official","src":[0]},{"text":"MT2025 yêu cầu tối đa 1 năm kinh nghiệm và đi làm từ 04/2025, tức điều kiện thay đổi theo năm.","basis":"official","src":[1]},{"text":"Lịch sử (2019–2021): các đợt cũ loại ứng viên đã vào vòng Assessment Center năm trước. Trang MT2025/MT2026 không còn nêu quy định này, nên hãy kiểm tra lại điều kiện của chu kỳ mới.","basis":"official","src":[5,10]}],"functions":[{"text":"Trang MT2026 giới thiệu các mảng Sales, Marketing, People & Culture, Operations (gồm Supply Chain), và có mô tả cho Trade Marketing, Media & Digital Marketing, Finance.","basis":"official","src":[0]},{"text":"MT2025: Marketing, Finance, People & Culture, Supply Chain & Logistics, Operations - Manufacturing, Sales.","basis":"official","src":[6]}],"stages":[{"name":"Application","what":"Nộp hồ sơ online trên careers.suntorypepsico.vn; trang nhắc đọc kỹ hướng dẫn và không bỏ sót phần nào trong form (MT2026: hạn 31/12/2025).","tips":["Nộp sớm: MT2026 tặng bài aptitude mẫu cho ứng viên nộp trước 07/12/2025.","Chọn function phù hợp; trang có 'interest test' để gợi ý mảng phù hợp."],"basis":"official","src":[0,2]},{"name":"Testing","what":"Link bài test gửi qua email; chỉ được làm một lần và phải hoàn thành trước hạn. Bài aptitude test (MT2025 gọi là cognitive test) bằng tiếng Anh; trang tuyển dụng khuyên tìm bài mẫu để làm quen.","tips":["Chỉ mở link khi đã sẵn sàng, ở nơi yên tĩnh, mạng ổn định, vì chỉ có một lượt.","Ôn các dạng aptitude phổ biến (numerical, verbal, logical) bằng tiếng Anh. Đây là gợi ý chung (general): công ty không công bố cấu trúc bài."],"basis":"official","src":[0,1]},{"name":"Initial Interview","what":"Phỏng vấn bằng cả tiếng Việt và tiếng Anh, nhằm hiểu về bạn, động lực và định hướng nghề nghiệp.","tips":["Chuẩn bị trả lời song ngữ: giới thiệu bản thân, động lực chọn function.","Dùng STAR, liên hệ với giá trị Yatte Minahare (dám thử, quyết tâm)."],"basis":"official","src":[0]},{"name":"Career Camp (Business Case & Panel Interview)","what":"MT2026: Business Case và Panel Interview, bằng tiếng Việt và tiếng Anh. Công ty tìm các năng lực như teamwork, problem solving, leadership, decision making, innovation. MT2025: ba hoạt động Games, Business Case và Panel Interview.","tips":["Luyện case FMCG (tăng trưởng doanh số, phân phối, ra mắt sản phẩm) và trình bày trước hội đồng.","Thể hiện teamwork và decision making rõ ràng trong phần case nhóm."],"basis":"official","src":[0,1]}],"tests":[{"name":"Aptitude/Cognitive test (tiếng Anh)","provider":null,"format":"Bài aptitude (MT2026) / cognitive (MT2025) bằng tiếng Anh, làm một lần qua link email trước hạn. Trang tuyển dụng không nêu các phần, thời lượng hay nhà cung cấp.","basis":"official","src":[0,1]},{"name":"Pre-employment testing (Talegent) cho các chương trình MT","provider":"Talegent qua TalentView (theo case study của vendor; không kiểm chứng lại được, không rõ năm, không xác nhận cho chu kỳ hiện tại)","format":"Case study chỉ nêu việc dùng để sàng lọc ứng viên MT, không mô tả định dạng.","basis":"reported","src":[7]},{"name":"Virtual test (EQ, toán, tiếng Anh) – chia sẻ ứng viên","provider":null,"format":"Theo chia sẻ ứng viên trên Glassdoor (khoảng 2022; không kiểm chứng lại được): bài test online gồm EQ, toán và tiếng Anh, sau đó là phỏng vấn sơ bộ, vòng assessment và phỏng vấn cuối với VP. Số chia sẻ ít và đã cũ.","basis":"reported","src":[8]}],"values":{"name":"Core values của Suntory PepsiCo Việt Nam","items":["Growing for Good","Yatte Minahare","Giving Back to Society"],"basis":"official","src":[9]},"prep":["Theo dõi careers.suntorypepsico.vn từ giữa tháng 11. Chu kỳ MT2026 đóng ngày 31/12 và tặng bài test mẫu cho ai nộp trước 07/12.","Study guide: ôn các dạng aptitude phổ biến (numerical, verbal, logical) bằng tiếng Anh (general, công ty không công bố cấu trúc), vì bài test chỉ làm được một lần.","Mental math gym hằng ngày để tăng tốc tính phần trăm, tỷ lệ, tăng trưởng.","Luyện chủ đề Verbal bằng tiếng Anh và chủ đề DI (bảng, biểu đồ).","Làm Mock test 'Suntory PepsiCo-style' ít nhất 2 lần trước khi mở link bài thật.","Chuẩn bị phỏng vấn song ngữ Việt–Anh và câu chuyện STAR gắn với Yatte Minahare, Growing for Good, Giving Back to Society.","Luyện Business Case FMCG và trình bày trước panel cho vòng Career Camp."],"mock":{"title":"Suntory PepsiCo-style practice test","topics":{"Quant":6,"Logical":6,"Verbal":6,"DI":4,"SJT":0},"minutes":25,"navigation":true,"note":"Trang tuyển dụng chỉ nêu có bài aptitude/cognitive bằng tiếng Anh, làm một lần; không công bố các phần hay thời lượng. Bài aptitude thường gồm numerical, verbal và logical, nên tỷ trọng Quant/Logical/Verbal/DI ở đây là ước lượng chung (general), không phải cấu trúc bài thật.","basis":"general","src":[0,1]},"pitfalls":["Mở link test khi chưa sẵn sàng: bài chỉ làm được một lần.","Chủ quan với tiếng Anh: bài test bằng tiếng Anh, còn phỏng vấn và Career Camp bằng cả tiếng Việt lẫn tiếng Anh.","Bỏ lỡ mốc nộp sớm (MT2026: trước 07/12/2025) để nhận bài test mẫu.","Dùng điều kiện của năm cũ: số năm kinh nghiệm tối đa đã đổi từ 1 năm (MT2025) lên 2 năm (MT2026).","Nhầm với Graduate Engineering Talent hay Graduate Sales Talent (chương trình, yêu cầu và lịch khác) khi đọc tin."],"sources":[{"title":"Suntory PepsiCo - Management Trainee (MT2026)","url":"https://careers.suntorypepsico.vn/intro?id=171&meta_title=MT2026","publisher":"Suntory PepsiCo Vietnam","year":"2025","accessed":"2026-11-13"},{"title":"Suntory PepsiCo - Management Trainee (MT2025)","url":"https://careers.suntorypepsico.vn/intro?id=168&meta_title=%27MT2025%27","publisher":"Suntory PepsiCo Vietnam","year":"2024","accessed":"2026-11-13"},{"title":"[HCM/HN] Suntory PepsiCo Management Trainee 2026","url":"https://vieclam.tuoitre.vn/en/search-job/hcm-hn-suntory-pepsico-management-trainee-2026.35C629E7.html","publisher":"Việc làm Tuổi Trẻ / CareerViet","year":"2025","accessed":"2026-11-13"},{"title":"Suntory PepsiCo Vietnam Management Trainee 2025 Program","url":"https://cecs.tdtu.edu.vn/en/news/2024/suntory-pepsico-vietnam-management-trainee-2025-program","publisher":"Đại học Tôn Đức Thắng","year":"2024","accessed":"2026-11-13"},{"title":"Chương Trình Quản Trị Viên Tập Sự Suntory PepsiCo Management Trainee (tin đăng lại)","url":"https://enijobs.vn/chuong-trinh-quan-tri-vien-tap-su-suntory-pepsico-management-trainee/","publisher":"EniJobs","year":"2025","accessed":"2026-11-13"},{"title":"Why Suntory PepsiCo Vietnam Management Trainee Program 2021?","url":"https://vieclam.ctu.edu.vn/index.php/kinh-te-luat/1106-toan-quoc-chuong-trinh-tuyen-dung-quan-tri-vien-tap-su-cua-cong-ty-nuoc-giai-khat-hang-dau-viet-nam-suntory-pepsico-management-trainee-2021","publisher":"Đại học Cần Thơ","year":"2020","accessed":"2026-11-13"},{"title":"Chương Trình Quản Trị Viên Tập Sự Suntory PepsiCo Management Trainee 2025","url":"https://ybox.vn/tuyen-dung/hcm-hn-chuong-trinh-quan-tri-vien-tap-su-tai-tap-doan-da-quoc-gia-suntory-pepsico-management-trainee-2025-marketing-finance-people-and-culture-supply-chain-and-logistics-operations-manufacturing-sales-673d3e63925c5d71f62f8036?sortId=PEPSICO-MT2025","publisher":"YBOX","year":"2024","accessed":"2026-11-13"},{"title":"Suntory Pepsi - TalentView (case study của vendor)","url":"https://www.talentview.com/suntory-pepsi/","publisher":"TalentView","year":"không ghi","accessed":"2026-11-13"},{"title":"Suntory PepsiCo Vietnam Beverage Management Trainee Interview Experience & Questions","url":"https://www.glassdoor.com/Interview/Suntory-PepsiCo-Vietnam-Beverage-Management-Trainee-Interview-Questions-EI_IE809796.0,32_KO33,51.htm","publisher":"Glassdoor (chia sẻ ứng viên)","year":"2022","accessed":"2026-11-13"},{"title":"About us","url":"https://www.suntorypepsico.vn/en/about-us","publisher":"Suntory PepsiCo Vietnam","year":"2026","accessed":"2026-11-13"},{"title":"Suntory PepsiCo - Management Trainee (đợt 2019)","url":"https://careers.suntorypepsico.vn/intro?id=163","publisher":"Suntory PepsiCo Vietnam","year":"2019","accessed":"2026-11-13"}]},{"id":"frieslandcampina","name":"FrieslandCampina Vietnam (Dutch Lady)","program":"FrieslandCampina Global Traineeship (trước đây: FCV Management Trainee Program; đợt MTP Việt Nam cuối tìm được: 2023)","industry":"FMCG (Sữa & dinh dưỡng)","lastChecked":"2026-11-13","summary":"FrieslandCampina hiện tuyển quản trị viên tập sự qua Global Traineeship 3 năm: hai vị trí tại nước sở tại, mỗi vị trí 18 tháng, theo Global Commercial Track (Sales & Marketing) hoặc Global Functions Track (Supply Chain, IT, HR, Finance). Quy trình chính thức có 5 bước: Online Application, Online Assessment, Online Interview, Selection Day (bài tập nhóm), Job offer. Vị trí riêng cho Việt Nam gần nhất tìm được là Global Traineeship Commerce – Vietnam (chu kỳ 2025); danh sách vị trí chu kỳ 2026 (đã đóng 04/10/2026) không có Việt Nam. FCV MTP là chương trình quản trị viên tập sự hằng năm trước đây của FrieslandCampina Việt Nam, đợt cuối tìm được là 2023.","intake":{"text":"Global Traineeship chu kỳ 2026: mở đơn 01/09–04/10/2026, khoá mới bắt đầu 01/03/2027; danh sách vị trí mở của chu kỳ này không có Việt Nam. Vị trí Global Traineeship Commerce – Vietnam thuộc chu kỳ 2025. Đợt FCV MTP Việt Nam cuối tìm được: 2023 (hạn khoảng 20/01/2023, theo tin đăng lại).","basis":"official","src":[0,1,2,3]},"eligibility":[{"text":"Global Traineeship (chu kỳ 2026): tối thiểu bằng Cử nhân (ưu tiên ngành liên quan); không cần kinh nghiệm, dành cho sinh viên mới tốt nghiệp; tiếng Anh lưu loát; phải đang học hoặc vừa tốt nghiệp tại chính quốc gia ứng tuyển. Nhận ứng viên mọi quốc tịch.","basis":"official","src":[0]},{"text":"Global Traineeship Commerce – Vietnam (chu kỳ 2025): câu hỏi sàng lọc nhắc tốt nghiệp Cử nhân trước 09/2025, đủ 18 tuổi, đủ điều kiện làm việc toàn thời gian theo luật lao động Việt Nam. Về kinh nghiệm, các nguồn khác nhau (0–1 năm và 0–2 năm); trang chương trình chính thức ghi 'không cần kinh nghiệm'.","basis":"official","src":[2,0]}],"functions":[{"text":"Global Traineeship: Global Commercial Track (Sales & Marketing) và Global Functions Track (Supply Chain, IT, HR, Finance). Mỗi trainee giữ hai vị trí tại nước sở tại, mỗi vị trí 18 tháng; có tuần onboarding tại HQ Hà Lan và chuyến gặp cohort tại Malaysia sau vòng luân chuyển đầu.","basis":"official","src":[0]},{"text":"Chu kỳ 2026 mở Commerce tại Pakistan, Ivory Coast, Philippines, Indonesia; Supply Chain tại Indonesia; Finance tại Malaysia; GBDS tại Hungary. Không có Việt Nam.","basis":"official","src":[1]}],"stages":[{"name":"Online Application","what":"Nộp CV và thư động lực (motivational letter) qua website, trước hạn và đúng khu vực mình chọn.","tips":["Thư động lực nên trả lời rõ: vì sao chọn track này, vì sao FrieslandCampina, và bằng chứng về global mindset.","Kiểm tra quốc gia bạn ứng tuyển có vị trí mở không. Chu kỳ 2026 không có Việt Nam."],"basis":"official","src":[0,1]},{"name":"Online Assessment ('Test your fit')","what":"Bài đánh giá online đo motivation, cognitive abilities và cultural fit với FrieslandCampina.","tips":["Luyện các dạng cognitive ability phổ biến bằng tiếng Anh có bấm giờ (general, công ty không công bố định dạng).","Phần cultural fit: trả lời nhất quán, trung thực theo đúng con người bạn."],"basis":"official","src":[0]},{"name":"Online Interview","what":"Phỏng vấn online với HR và đại diện business, tập trung vào động lực với discipline đã chọn và với FrieslandCampina; đây cũng là lúc bạn đặt câu hỏi.","tips":["Chuẩn bị câu chuyện STAR thể hiện adaptability, collaboration, growth mindset.","Chuẩn bị 2–3 câu hỏi về vòng luân chuyển và mảng sữa/dinh dưỡng."],"basis":"official","src":[0]},{"name":"Selection Day","what":"Gặp đồng nghiệp tương lai, tìm hiểu công ty và tham gia một bài tập nhóm (group assignment) để đánh giá mức phù hợp văn hoá.","tips":["Trong bài tập nhóm: đóng góp ý tưởng có cấu trúc, lắng nghe và hỗ trợ người khác (general).","Thể hiện tinh thần hợp tác, phù hợp tiêu chí 'collaborative'."],"basis":"official","src":[0]},{"name":"Job offer","what":"Hoàn thành tất cả các vòng thì nhận offer trở thành Global Trainee.","tips":["Xác nhận ngày bắt đầu (chu kỳ 2026: 01/03/2027) và địa điểm ở nước sở tại."],"basis":"official","src":[0]}],"history":[{"text":"Lịch sử – FCV MTP 2023 (không còn áp dụng): 4 vòng gồm Application form, Aptitude test, Initial interview, Business Challenge kèm Final interview; tuyển Marketing, Sales, HR, Finance, lần đầu thêm Procurement; GPA ≥ 7.0/10, đi làm từ 04/2023 (theo tin đăng lại năm 2022–2023).","basis":"official","src":[3,4,5]},{"text":"Lịch sử – Business Challenge bản 2017: ứng viên làm nhóm 6–8 người giải một bài toán kinh doanh thật của FCV (khoảng 20–31/03/2017), trình bày trước Directors và Leadership Team, phỏng vấn cuối ngay trong ngày và có quyết định ngay sau đó.","basis":"official","src":[6]}],"tests":[{"name":"Online Assessment (motivation, cognitive abilities, cultural fit)","provider":null,"format":"Đo động lực, năng lực nhận thức và mức phù hợp văn hoá. Không công bố nhà cung cấp, số phần hay thời lượng.","basis":"official","src":[0]}],"values":{"name":"Tiêu chí Global Trainee (FrieslandCampina)","items":["Adaptable","Collaborative","Growth mindset","Eager to learn","Ambitious","Global mindset"],"basis":"official","src":[0]},"prep":["Global Traineeship 2026 (01/09–04/10/2026) đã đóng và không có vị trí riêng cho Việt Nam; theo dõi careers.frieslandcampina.com/vnm khoảng tháng 8–9/2027 xem chu kỳ mới có mở cho Việt Nam không.","Study guide: ôn các dạng cognitive ability phổ biến (logic, số liệu, đọc hiểu tiếng Anh), vì định dạng bài Online Assessment chưa được công bố.","Mental math gym để xử lý nhanh số liệu doanh số và thị phần.","Luyện chủ đề DI và Verbal tiếng Anh: yêu cầu tiếng Anh lưu loát cho mọi track.","Làm Mock test 'FrieslandCampina-style' để kiểm tra nền tảng tổng quát, kèm vài câu SJT cho phần cultural fit.","Viết thư động lực bằng tiếng Anh, gắn với adaptable, collaborative, growth mindset, global mindset.","Luyện bài tập nhóm 45 phút với bạn bè để chuẩn bị cho Selection Day."],"mock":{"title":"FrieslandCampina-style practice test","topics":{"Quant":4,"Logical":5,"Verbal":4,"DI":3,"SJT":4},"minutes":20,"navigation":true,"note":"Online Assessment chính thức đo motivation, cognitive abilities và cultural fit, nhưng không công bố định dạng. Mock này luyện phần cognitive (Quant/Logical/Verbal/DI) và thêm vài câu SJT làm đại diện gần đúng cho phần fit. App không mô phỏng được bài đo động lực/văn hoá thật; tỷ trọng là ước lượng chung.","basis":"general","src":[0]},"pitfalls":["Chuẩn bị theo quy trình FCV MTP cũ (2021–2023), trong khi kênh hiện tại là Global Traineeship với 5 bước khác.","Ứng tuyển ở quốc gia mình không học hay tốt nghiệp: trang chính thức yêu cầu đang học hoặc vừa tốt nghiệp tại quốc gia ứng tuyển.","Bỏ lỡ cửa sổ nộp đơn ngắn (chu kỳ 2026: khoảng 5 tuần, 01/09–04/10).","Thư động lực chung chung, không nói rõ vì sao chọn track và FrieslandCampina."],"sources":[{"title":"Global Traineeship at FrieslandCampina","url":"https://careers.frieslandcampina.com/vnm/en/page/global-traineeship-frieslandcampina","publisher":"FrieslandCampina","year":"2026","accessed":"2026-11-13"},{"title":"Open vacancies Global Traineeship","url":"https://careers.frieslandcampina.com/global/en/story/open-vacancies-global-traineeship","publisher":"FrieslandCampina","year":"2026","accessed":"2026-11-13"},{"title":"Global Traineeship Commerce - Vietnam (vacancy 56927, chu kỳ 2025)","url":"https://careers.frieslandcampina.com/mys/en/vacancy/56927","publisher":"FrieslandCampina","year":"2025","accessed":"2026-11-13"},{"title":"Friesland Campina Việt Nam: Tuyển vị trí Quản Trị Viên Tập Sự (FCV MTP 2023)","url":"https://www.brandsvietnam.com/congdong/topic/329829-hcm-friesland-campina-viet-nam-tuyen-vi-tri-quan-tri-vien-tap-su","publisher":"Brands Vietnam","year":"2022","accessed":"2026-11-13"},{"title":"Chương Trình Quản Trị Viên Tập Sự Management Trainee 2023 Do Tập Đoàn FrieslandCampina Vietnam Tổ Chức","url":"https://ivolunteervietnam.com/chuong-trinh-quan-tri-vien-tap-su-management-trainee-2023-do-tap-doan-frieslandcampina-vietnam-to-chuc.html","publisher":"iVolunteer Vietnam","year":"2022","accessed":"2026-11-13"},{"title":"FrieslandCampina Vietnam - Management Trainee Program 2023 (FCV MTP 2023)","url":"https://enijobs.vn/frieslandcampina-vietnam-management-trainee-program-2023-fcv-mtp-2023/","publisher":"EniJobs","year":"2022","accessed":"2026-11-13"},{"title":"FrieslandCampina Viet Nam Management Trainee Program (FCV-MT)","url":"https://vieclam.ou.edu.vn/ban-tin/frieslandcampina-viet-nam-management-trainee-program-fcv-mt-.35a52783/vi","publisher":"Đại học Mở TP.HCM","year":"2017","accessed":"2026-11-13"}]},{"id":"nestle","name":"Nestlé Vietnam","program":"Nestlé #SparkTheNext Leaders Program (NSLP) - Management Trainee","industry":"FMCG / Food & Beverage","lastChecked":"2026-11-13","summary":"NSLP là chương trình Management Trainee 18 tháng của Nestlé Việt Nam, gồm 2 giai đoạn (12 tháng đầu luân chuyển đa chức năng), dành cho sinh viên năm cuối hoặc mới tốt nghiệp có dưới 1 năm kinh nghiệm. Quy trình 4 vòng: Online Application & Assessment → Initial Interview → Nestlé Camp/Sales Challenge (assessment centre) → Final Interview với hội đồng lãnh đạo. Nesternship (thực tập) là đường tắt vào NSLP.","intake":{"text":"NSLP – Management Trainee 2027 ĐÃ MỞ ĐƠN trên cổng việc làm Nestlé (đăng ngày 11/11/2026, bắt đầu làm việc tháng 5/2027). Trang không ghi hạn nộp; dữ liệu tin đăng cho thấy tin hết hiệu lực ngày 20/12/2026, nên nộp sớm trước mốc này. Đợt trước (NSLP 2026): Online Assessment 10/11–15/12/2025, Initial Interview tháng 1/2026, Nest Camp và Final Interview tháng 3–4/2026, bắt đầu tháng 5/2026. NSLP 2025: hạn cuối tháng 12/2024, bắt đầu tháng 5/2025.","basis":"official","src":[2,1,3]},"eligibility":[{"text":"Sinh viên năm cuối hoặc mới tốt nghiệp, dưới 1 năm kinh nghiệm toàn thời gian.","basis":"official","src":[2,1]},{"text":"GPA từ 2.8/4 (hoặc 7/10) trở lên.","basis":"official","src":[2,1]},{"text":"NSLP 2027: đi làm toàn thời gian được từ tháng 5/2027; tự tin tiếng Anh, giao tiếp tốt; tư duy phân tích, làm việc nhóm, thích nghi nhanh.","basis":"official","src":[2]},{"text":"Sinh viên còn đang học có thể đi đường Nesternship (thực tập): Nestlé Việt Nam gọi đây là đường tắt (fast-track) vào NSLP.","basis":"official","src":[6]}],"functions":[{"text":"NSLP 2027 tuyển 10 mảng: Sales (GT/MT/eCommerce/Trade Marketing), Commercial (Marketing), Consumer Market Intelligence, Finance & Control, Information Technology, Supply Chain, Factory Human Resources, Engineering, Production, Quality Assurance; nơi làm việc TP.HCM, Đồng Nai, Hưng Yên.","basis":"official","src":[2]},{"text":"Cấu trúc chương trình: 18 tháng, 2 giai đoạn, 12 tháng đầu luân chuyển đa chức năng (cross-function rotation).","basis":"official","src":[0]}],"stages":[{"name":"Online Application & Assessment (Round 1)","what":"Nộp đơn qua cổng Nestlé, hoàn thiện hồ sơ và làm các bài đánh giá online. Tin NSLP 2027 chính thức chỉ ghi 'online assessments', không nêu cấu trúc. Tham khảo (có thể đã lỗi thời): tin NSLP 2023 trên nền tảng Pulsifi mô tả Numerical reasoning (15 phút), Logical reasoning (10 phút), 3 bài đánh giá tính cách (25 phút) và video interview ngắn 3 câu (5 phút).","tips":["Luyện Quant (tỉ lệ, phần trăm, đọc bảng) với áp lực khoảng 1 phút/câu.","Luyện Logical (quy luật hình, chuỗi) có bấm giờ ngắn.","Bài tính cách: trả lời trung thực, nhất quán.","Tập trả lời video ngắn: ứng viên báo cáo thời gian chuẩn bị ngắn."],"basis":"official","src":[2,4,7]},{"name":"Initial Interview (Round 2)","what":"Phỏng vấn vòng đầu ('Show us who you are and what drives you'); đợt 2026 diễn ra tháng 1/2026. Nội dung chi tiết: Chưa có thông tin công khai đáng tin cậy.","tips":["Chuẩn bị phần giới thiệu bản thân 1–2 phút bằng tiếng Anh, gắn với function ứng tuyển.","Chuẩn bị câu chuyện STAR thể hiện tôn trọng, hợp tác, chủ động."],"basis":"official","src":[1,2]},{"name":"Nestlé Camp / Sales Challenge – Assessment Center (Round 3)","what":"Assessment centre: theo tin trên cổng Nestlé, ứng viên giải các vấn đề kinh doanh thực tế và gặp gỡ lãnh đạo Nestlé. Thời lượng: Nestlé chưa công bố (một trang tổng hợp việc làm không chính thức ghi 2 ngày). Đợt 2026: tháng 3–4/2026.","tips":["Luyện case nhóm FMCG (kênh phân phối, giá, khuyến mãi, chuỗi cung ứng) có trình bày số liệu.","Thể hiện vai trò trong nhóm: cấu trúc vấn đề, quản lý thời gian, tổng hợp ý.","Với Sales Challenge: ôn tính toán doanh số, biên lợi nhuận, mục tiêu theo kênh."],"basis":"official","src":[2,1]},{"name":"Final Interview (Round 4)","what":"Phỏng vấn cuối với hội đồng lãnh đạo kinh doanh (business leaders panel); đợt 2026: tháng 3–4/2026, offer và bắt đầu tháng 5/2026.","tips":["Chuẩn bị 'Why Nestlé / Why function' gắn với purpose và brand Nestlé tại Việt Nam.","Chuẩn bị kế hoạch phát triển 18 tháng của bản thân trong NSLP."],"basis":"official","src":[1,2]}],"tests":[{"name":"Numerical reasoning","provider":"Pulsifi (nền tảng tuyển dụng/đánh giá được dùng cho NSLP 2023; chưa rõ nhà phát triển bài test)","format":"15 phút (NSLP 2023, có thể đã lỗi thời; tin 2027 không nêu cấu trúc).","basis":"official","src":[4]},{"name":"Logical reasoning","provider":"Pulsifi (nền tảng tuyển dụng/đánh giá được dùng cho NSLP 2023; chưa rõ nhà phát triển bài test)","format":"10 phút (NSLP 2023, có thể đã lỗi thời; tin 2027 không nêu cấu trúc).","basis":"official","src":[4]},{"name":"Personality assessments","provider":"Pulsifi (nền tảng tuyển dụng/đánh giá được dùng cho NSLP 2023; chưa rõ nhà phát triển bài test)","format":"3 bài đánh giá tính cách, tổng 25 phút (NSLP 2023, có thể đã lỗi thời; tin 2027 không nêu cấu trúc).","basis":"official","src":[4]},{"name":"Short video interview","provider":"Pulsifi (nền tảng tuyển dụng/đánh giá được dùng cho NSLP 2023; chưa rõ nhà phát triển bài test)","format":"3 câu hỏi, khoảng 5 phút (NSLP 2023, có thể đã lỗi thời; tin 2027 không nêu cấu trúc). Ứng viên ở Việt Nam báo cáo thời gian chuẩn bị mỗi câu ngắn (reported).","basis":"official","src":[4,7]}],"values":{"name":"Nestlé values – rooted in respect","items":["Respect for ourselves","Respect for others","Respect for diversity","Respect for the future"],"basis":"official","src":[5]},"prep":["Ngay bây giờ (tháng 11/2026): NSLP 2027 đã mở đơn trên cổng việc làm Nestlé (đăng 11/11/2026); trang không ghi hạn nhưng tin hết hiệu lực 20/12/2026, nên nộp sớm.","Study guide: đọc phần numerical/logical reasoning và bài tính cách (định dạng NSLP 2023, có thể đã thay đổi).","Mental math gym hằng ngày: bài numerical khoảng 15 phút cần tính phần trăm, tỉ lệ nhanh.","Luyện chủ đề Quant và Logical có bấm giờ; thêm DI với bảng số liệu bán hàng FMCG.","Làm Mock test 'Nestlé-style' 25 phút để quen nhịp làm bài.","Tập video interview 3 câu bằng tiếng Anh với thời gian chuẩn bị ngắn.","Chuẩn bị case nhóm và Sales Challenge cho Nestlé Camp; ôn 4 giá trị 'rooted in respect' để dùng trong phỏng vấn.","Cân nhắc Nesternship nếu còn đang học: Nestlé gọi đây là đường tắt vào NSLP."],"mock":{"title":"Nestlé-style practice test","topics":{"Quant":8,"Logical":6,"Verbal":2,"DI":4,"SJT":4},"minutes":25,"navigation":true,"note":"Dựa trên mô tả NSLP 2023 (có thể đã lỗi thời; tin 2027 chỉ ghi 'online assessments'): numerical 15 phút, logical 10 phút, 3 bài tính cách, video 3 câu. Trọng tâm Quant/DI và Logical, thêm ít SJT thay cho phần tính cách (app không chấm được bài tính cách). Phần video interview cần luyện riêng. Chưa có nguồn về việc có quay lại câu trước được hay không nên để bật điều hướng.","basis":"general","src":[4]},"pitfalls":["Nộp muộn: tin NSLP 2027 hết hiệu lực 20/12/2026; đợt 2026 hạn Online Assessment là 15/12/2025 (official).","Chủ quan bài numerical: ứng viên báo cáo bài không khó nhưng thời gian rất ngắn (reported).","Không tập trước video interview có thời gian chuẩn bị ngắn (reported).","Ở Nestlé Camp chỉ tập trung ý tưởng mà bỏ qua tính khả thi và số liệu (general).","Không đáp ứng GPA 2.8/4 (7/10) hoặc không thể đi làm từ tháng 5 (official)."],"sources":[{"title":"Nestlé #SparkTheNext Leaders Program","url":"https://www.nestle.com.vn/jobs/nestle-needs-youth/nestle-spark-the-next-program","publisher":"Nestlé Việt Nam","year":"2025","accessed":"2026-11-13"},{"title":"Nestlé #SparkTheNext Leaders Program 2026 - timeline & eligibility","url":"https://www.nestle.com.vn/en/node/431841","publisher":"Nestlé Việt Nam","year":"2025","accessed":"2026-11-13"},{"title":"Nestlé #SparkTheNext Leaders Program - Management Trainee 2027 (Nestlé Vietnam Management Trainee)","url":"https://jobdetails.nestle.com/job/Ho-Chi-Minh-Nestl%C3%A9-Vietnam-Management-Trainee-70000/1456413233/","publisher":"Nestlé Jobs","year":"2026","accessed":"2026-11-13"},{"title":"[HCM/Đồng Nai] Nestlé #SparkTheNext Leaders 2025 - Management Trainee Program","url":"https://ybox.vn/tuyen-dung/hcm-dong-nai-chuong-trinh-tuyen-quan-tri-vien-tap-su-nestle-sparkthenext-leaders-2025-management-trainee-program-cua-tap-doan-da-quoc-gia-nestle-67373edc3a0dc87edea64ef5","publisher":"YBOX","year":"2024","accessed":"2026-11-13"},{"title":"Nestlé #SparkTheNext Leaders Program (NSLP) 2023 (không truy cập được khi kiểm tra 2026-11-13; dữ liệu 2023)","url":"https://job.pulsifi.me/companies/nestle-vn/33360107-3516-4883-801e-8bf9538d09e5/nestle-sparkthenext-leaders-program-nlsp-2023","publisher":"Pulsifi (cổng tuyển dụng Nestlé Việt Nam)","year":"2022","accessed":"2026-11-13"},{"title":"Our purpose and values","url":"https://www.nestle.in/about-us/our-purpose","publisher":"Nestlé India","year":"2025","accessed":"2026-11-13"},{"title":"What is Nesternship?","url":"https://www.nestle.com.vn/vi/what-nesternship","publisher":"Nestlé Việt Nam","year":"2026","accessed":"2026-11-13"},{"title":"Nestlé Interview Questions in Vietnam (candidate-reported)","url":"https://www.glassdoor.com/Interview/Nestl%C3%A9-Vietnam-Interview-Questions-EI_IE3492.0,6_IL.7,14_IN251.htm","publisher":"Glassdoor","year":"n/a","accessed":"2026-11-13"}]},{"id":"vinamilk","name":"Vinamilk (Công ty Cổ phần Sữa Việt Nam)","program":"Vinamilk Graduate Talent Program (GTP)","industry":"FMCG / Sữa","lastChecked":"2026-11-13","summary":"Graduate Talent Program là chương trình tuyển dụng và phát triển tài năng trẻ 12 tháng tại trụ sở chính Vinamilk (TP.HCM), mùa 1 năm 2025, mùa 2 năm 2026. Ứng viên trúng tuyển là nhân viên chính thức ngay từ ngày đầu, làm xuyên suốt tại một phòng ban (phát triển kiểu T-shaped qua dự án liên phòng ban), không luân chuyển như MT truyền thống. Quy trình: Application → Aptitude Test online (5 phần, có SJT) → Phỏng vấn chuyên sâu online → Phỏng vấn với Ban lãnh đạo (online hoặc tại trụ sở).","intake":{"text":"GTP 2026: nộp hồ sơ 27/06–26/07/2026; Kiểm tra năng lực tháng 7/2026; Phỏng vấn chuyên sâu tháng 8/2026; Phỏng vấn với Ban lãnh đạo tháng 9/2026; gia nhập tháng 10/2026. GTP 2025: ứng tuyển 06/06–06/07/2025, test 06–07/2025, phỏng vấn chuyên sâu 07–08/2025, phỏng vấn cuối 08/2025 tại TP.HCM, onboarding 09/2025. Hai mùa đều mở đơn khoảng tháng 6 (mùa sau chưa công bố).","basis":"official","src":[0,1]},"eligibility":[{"text":"Sinh viên năm cuối hoặc đã tốt nghiệp, dưới 2 năm kinh nghiệm (GTP 2026).","basis":"official","src":[0,2]},{"text":"GPA từ 7/10 trở lên (hoặc tương đương); có tiềm năng lãnh đạo, tư duy logic, kỹ năng giải quyết vấn đề và tiếng Anh tốt (GTP 2026).","basis":"official","src":[2]},{"text":"Có thể làm việc toàn thời gian từ tháng 10/2026 (mùa 2025: từ tháng 9/2025). Địa điểm: Văn phòng Vinamilk, số 10 Tân Trào, TP.HCM.","basis":"official","src":[0,1,2]}],"functions":[{"text":"GTP 2026 tuyển 10 lĩnh vực / 19 vị trí (số vị trí): Brand Design (1), Brand Management (2), E-commerce (1), Finance (1), Internal Control & Audit (3), Manufacturing Excellence (1), Modern Trade (2), Research & Development (1), Retail Chain (2), Tech & Data (5). Ứng viên chọn tối đa 2 nguyện vọng, xét theo thứ tự ưu tiên.","basis":"official","src":[0,2]}],"stages":[{"name":"Nộp hồ sơ ứng tuyển (Online application)","what":"Nộp hồ sơ trực tuyến trên trang GTP (2026: 27/06–26/07), chọn tối đa 2 nguyện vọng vị trí. (Một ứng viên trên diễn đàn kể có bước lọc CV trước khi nhận link bài test — reported, chưa xác minh.)","tips":["Đọc JD từng vị trí và chọn 2 nguyện vọng thật sự phù hợp chuyên ngành, vì GTP phát triển chuyên sâu trong một phòng ban.","Trong CV/đơn, đưa ví dụ cụ thể thể hiện 4 'chất Vinamilk': đào sâu, quyết liệt, tự chủ, luôn cầu tiến.","Ghi rõ GPA ≥ 7/10 và trình độ tiếng Anh."],"basis":"official","src":[0,3]},{"name":"Kiểm tra năng lực (Aptitude Test, online)","what":"Bài kiểm tra trực tuyến (2026: tháng 7) gồm 5 phần theo FAQ chính thức: phán đoán tình huống, phân tích dữ liệu, tính toán số liệu, tư duy logic, tư duy ngôn ngữ. (Ứng viên trên diễn đàn kể điểm test dùng để xếp thứ tự mời phỏng vấn — reported, chưa xác minh.)","tips":["Luyện đủ 5 mảng, kể cả SJT và Verbal — không chỉ Logical/DI.","Dùng Mental math gym để tính %, tỷ lệ, tăng trưởng nhanh cho phần tính toán và phân tích dữ liệu."],"basis":"official","src":[0,3]},{"name":"Phỏng vấn chuyên sâu (In-depth Interview, online)","what":"Phỏng vấn chuyên sâu trực tuyến với quản lý trực tiếp và bộ phận tuyển dụng (2026: tháng 8; 2025: tháng 7–8). Một số vị trí yêu cầu làm bài tập tình huống chuyên môn (Functional Case Study) trước buổi phỏng vấn.","tips":["Ôn kiến thức chuyên môn của vị trí để sẵn sàng cho Functional Case Study.","Chuẩn bị 4–5 câu chuyện STAR gắn với 4 'chất Vinamilk'.","Kiểm tra trước thiết bị, mạng, ánh sáng cho phỏng vấn online."],"basis":"official","src":[0,1]},{"name":"Phỏng vấn với Ban lãnh đạo (Final)","what":"Vòng cuối với sự tham gia của các Giám đốc khối/phòng, online hoặc offline tại Trụ sở chính Vinamilk, TP.HCM (2026: tháng 9). Mùa 2025 vòng cuối diễn ra tại TP.HCM (08/2025). Hình thức câu hỏi cụ thể: Chưa có thông tin công khai đáng tin cậy.","tips":["Chuẩn bị quan điểm cá nhân về một vấn đề/cơ hội của Vinamilk trong lĩnh vực bạn ứng tuyển.","Giữ câu trả lời nhất quán với vòng phỏng vấn chuyên sâu."],"basis":"official","src":[0,1]}],"tests":[{"name":"Kiểm tra năng lực (Aptitude Test)","provider":null,"format":"Trực tuyến, gồm 5 phần (theo FAQ chính thức GTP 2026): Phán đoán tình huống (SJT), Phân tích dữ liệu, Tính toán số liệu, Tư duy logic, Tư duy ngôn ngữ. Thời lượng, số câu và nhà cung cấp chưa được công bố.","basis":"official","src":[0]}],"values":{"name":"4 'chất Vinamilk' (tiêu chí ứng viên GTP 2026)","items":["Đào sâu (suy nghĩ thấu đáo, phân tích tường tận)","Quyết liệt (kiên định với mục tiêu, không bỏ cuộc)","Tự chủ (dám gánh vác, chịu trách nhiệm)","Luôn cầu tiến (không ngừng đặt ra mục tiêu thách thức hơn)"],"basis":"official","src":[2,0]},"prep":["Đọc Study guide cho cả 5 mảng của bài Aptitude (SJT, DI, Quant, Logical, Verbal) và luyện chủ đề từng mảng có bấm giờ.","Luyện Mental math gym mỗi ngày 10 phút: %, tăng trưởng, tỷ lệ — phục vụ phần tính toán số liệu và phân tích dữ liệu.","Làm 'Vinamilk-style practice test' trong Mock test ít nhất 3 lần, ghi lại dạng câu sai theo từng mảng.","Luyện chủ đề SJT: đọc kỹ bối cảnh, ưu tiên phương án thể hiện tự chủ, đào sâu vấn đề và vì khách hàng.","Viết sẵn 4 câu chuyện STAR, mỗi câu chứng minh một 'chất Vinamilk' (đào sâu, quyết liệt, tự chủ, luôn cầu tiến).","Ôn kiến thức chuyên môn của vị trí đã chọn để sẵn sàng cho Functional Case Study.","Theo dõi Life At Vinamilk (Facebook/LinkedIn/Threads/TikTok) từ tháng 5–6 để không lỡ thời điểm mở đơn."],"mock":{"title":"Vinamilk-style practice test","topics":{"Quant":4,"Logical":4,"Verbal":4,"DI":4,"SJT":4},"minutes":25,"navigation":true,"note":"Các mảng theo FAQ chính thức (5 phần: phán đoán tình huống, phân tích dữ liệu, tính toán số liệu, tư duy logic, tư duy ngôn ngữ), chia đều 4 câu mỗi mảng. Số câu, thời gian và việc quay lại câu trước của bài thật chưa được công bố, nên phần thời lượng và điều hướng chỉ là mô phỏng.","basis":"official","src":[0]},"pitfalls":["Chỉ ôn Logical/DI mà bỏ qua SJT và Verbal — bài test chính thức có 5 phần (official).","Nhầm GTP là chương trình MT luân chuyển: GTP làm xuyên suốt tại một phòng ban trong 12 tháng (official).","Nộp sát hạn: cửa sổ mở đơn chỉ khoảng 1 tháng (06/06–06/07/2025; 27/06–26/07/2026) (official).","Không chuẩn bị chuyên môn cho vị trí có Functional Case Study trước phỏng vấn chuyên sâu (official)."],"sources":[{"title":"Vinamilk Graduate Talent Program 2026 (gồm Quy trình tuyển dụng, Q&A, Chất Vinamilk)","url":"https://careers.vinamilk.com.vn/vi/graduatetalent-program","publisher":"Vinamilk","year":"2026","accessed":"2026-11-13"},{"title":"[HCM] Vinamilk Graduate Talent Program - Chương Trình Tuyển Dụng Tài Năng Trẻ 2025","url":"https://ybox.vn/tuyen-dung/hcm-vinamilk-graduate-talent-program-chuong-trinh-tuyen-dung-tai-nang-tre-tai-cong-ty-sua-viet-nam-vinamilk-full-time-2025-6842f6b9e7b9c57a7a563ba7","publisher":"YBOX","year":"2025","accessed":"2026-11-13"},{"title":"[HCM] Vinamilk Graduate Talent Program 2026 - Chương Trình Tuyển Dụng Nhân Tài Trẻ 2026","url":"https://ybox.vn/tuyen-dung/hcm-vinamilk-graduate-talent-program-chuong-trinh-phat-trien-tai-nang-tre-tai-cong-ty-kinh-doanh-sua-viet-nam-vinamilk-full-time-2026-6a3fe28dc1ee587f48b135ea","publisher":"YBOX","year":"2026","accessed":"2026-11-13"},{"title":"Nhận email từ Vinamilk Graduate Talent Program (diễn đàn ứng viên)","url":"https://voz.vn/t/nhan-email-tu-vinamilk-graduate-talent-program.1121624/","publisher":"VOZ Forum","year":"2025","accessed":"2026-11-13"}]},{"id":"techcombank","name":"Techcombank (Ngân hàng TMCP Kỹ Thương Việt Nam)","program":"Techcombank Future Gen (TFG)","industry":"Ngân hàng","lastChecked":"2026-11-13","summary":"Techcombank Future Gen là chương trình Quản trị viên tập sự (Management Trainee) thường niên, kéo dài 24 tháng, luân chuyển mỗi 6 tháng trong một trong 4 Capability Stream: Technology, Data & AI, Business, General Management; tất cả vị trí ở Hội sở Hà Nội. Tên chương trình gắn với năm onboarding (TFG 2027 tuyển năm 2026). Điểm khác biệt: vừa có Aptitude Test vừa có Functional Test theo stream, Remote Interview, Assessment Center rồi Panel Interview.","intake":{"text":"TFG 2027 (trang chính thức): nhận hồ sơ 24/07–30/09 (YBOX ghi 30/07–30/09/2026); Remote Interview và Aptitude Test tháng 8–10; Functional Test tháng 8–10 (bản tiếng Anh ghi September–October); Assessment Center tháng 10; Panel Interview tháng 11; Offer tháng 11–12/2026 (trang chính thức ghi không thống nhất: bản Việt 'Tháng 11', bản Anh 'December'); onboarding tháng 1/2027. TFG 2026 (mùa 5): nhận hồ sơ 28/07–30/09/2025 (theo báo chí, chưa xác minh từ nguồn chính thức). Thường đóng đơn 30/9.","basis":"official","src":[0,1,3]},"eligibility":[{"text":"Sinh viên năm cuối, mới tốt nghiệp hoặc dưới 2 năm kinh nghiệm làm việc toàn thời gian; tiếng Anh nói và viết thành thạo (theo yêu cầu stream).","basis":"official","src":[0,1]},{"text":"Làm việc toàn thời gian theo hợp đồng lao động và nộp bằng tốt nghiệp trước thời điểm onboarding (dự kiến tháng 1/2027 cho TFG 2027).","basis":"official","src":[0]},{"text":"Làm việc toàn thời gian tại Hội sở Hà Nội (06 Quang Trung / 119 Trần Duy Hưng) – TFG 2027; form ứng tuyển hỏi bạn có sẵn sàng làm việc tại Hà Nội.","basis":"official","src":[0]}],"functions":[{"text":"TFG 2027 tuyển 4 stream: Technology, Data & AI, Business, General Management (trang chính thức vẫn hiển thị thẻ Digital nhưng form ứng tuyển chỉ có 4 stream). Luân chuyển mỗi 6 tháng giữa các chức năng/khối trong stream.","basis":"official","src":[0,1]},{"text":"TFG 2025 (mùa 4): 4 nhóm Technology, Digital & Data, Business, General Management; thời lượng 24 tháng.","basis":"official","src":[2]}],"stages":[{"name":"Online application","what":"Nộp đơn trên trang tuyển dụng Techcombank (TFG 2027: 24/07–30/09/2026), chọn Capability Stream và xác nhận khả năng làm việc tại Hà Nội.","tips":["Chọn stream phù hợp nền tảng, vì Functional Test theo stream.","Thể hiện Aspiration – Ability – Commitment bằng thành tích định lượng."],"basis":"official","src":[0]},{"name":"Remote Interview","what":"Phỏng vấn từ xa (tháng 8–10/2026). Hình thức chính xác (gọi điện hay video ghi hình): Chưa có thông tin công khai đáng tin cậy.","tips":["Chuẩn bị phần giới thiệu 60–90 giây và lý do chọn Techcombank/stream.","Luyện trả lời bằng cả tiếng Việt và tiếng Anh, vì các stream yêu cầu tiếng Anh thành thạo."],"basis":"official","src":[0]},{"name":"Aptitude Test","what":"Bài test năng lực tư duy (tháng 8–10/2026). Định dạng chi tiết và nhà cung cấp chưa được công bố công khai.","tips":["Luyện đủ Quant, Logical, Verbal, DI có bấm giờ.","Luyện bài Verbal bằng tiếng Anh."],"basis":"official","src":[0]},{"name":"Functional Test","what":"Bài kiểm tra chuyên môn theo stream (tháng 8–10/2026, chính thức). Stream Data & AI chính thức yêu cầu làm việc được với Python, SQL, Power BI. Theo một đơn vị luyện thi (không chính thức, reported): Data & AI có thể gồm trắc nghiệm và coding; Business nên ôn quản trị doanh nghiệp, tài chính tiền tệ, ngân hàng thương mại.","tips":["Ôn kiến thức nền của stream (ngân hàng thương mại, tài chính; hoặc SQL/Python/Power BI với Data & AI).","Đọc báo cáo thường niên Techcombank để nắm mô hình kinh doanh."],"basis":"official","src":[0,4]},{"name":"Assessment Center","what":"Vòng Assessment Center (tháng 10/2026). Nội dung chi tiết chưa được công bố chính thức.","tips":["Luyện thảo luận case nhóm: lắng nghe, tổng hợp ý, quản lý thời gian.","Luyện thuyết trình ngắn có cấu trúc (vấn đề – phân tích – đề xuất)."],"basis":"official","src":[0]},{"name":"Panel Interview","what":"Phỏng vấn hội đồng (tháng 11/2026), sau đó Offer (tháng 11–12) và onboarding tháng 1/2027.","tips":["Chuẩn bị tầm nhìn 2–3 năm của bản thân trong ngân hàng.","Có quan điểm về chiến lược số hóa/dữ liệu của Techcombank."],"basis":"official","src":[0]}],"tests":[{"name":"Aptitude Test","provider":null,"format":"Số phần, thời gian và nhà cung cấp chưa được công bố công khai.","basis":"official","src":[0]},{"name":"Functional Test (theo stream)","provider":null,"format":"Kiến thức chuyên môn theo stream (chính thức). Chi tiết dạng bài (trắc nghiệm + coding cho Data & AI) chỉ đến từ đơn vị luyện thi, chưa xác minh.","basis":"reported","src":[0,4]}],"values":{"name":"Tiêu chí ứng viên TFG và giá trị cốt lõi","items":["Aspiration – Ability – Commitment (khát vọng, năng lực, cam kết)","Learning agility, analytical thinking, passion for innovation, growth mindset","5 giá trị cốt lõi (báo cáo thường niên 2022): Khách hàng là trọng tâm; Đổi mới và Sáng tạo; Hợp tác vì mục tiêu chung; Làm việc hiệu quả; Phát triển bản thân","Phương châm thương hiệu: 'Vượt trội hơn mỗi ngày'"],"basis":"official","src":[0,5,1]},"prep":["Học Study guide và luyện chủ đề Quant, Logical, Verbal, DI — ưu tiên phiên bản tiếng Anh.","Mental math gym hằng ngày để tính lãi suất, tăng trưởng, tỷ suất nhanh.","Làm 'Techcombank-style practice test' trong Mock test, mục tiêu hoàn thành đúng giờ.","Ôn kiến thức Functional theo stream (ngân hàng thương mại/tài chính cho Business; SQL/Python/Power BI cho Data & AI).","Luyện case nhóm và thuyết trình 5 phút để chuẩn bị Assessment Center.","Chuẩn bị câu chuyện STAR chứng minh Aspiration – Ability – Commitment.","Quyết định trước việc làm việc tại Hà Nội; đặt nhắc nhở tháng 7 để nộp đơn sớm, trước hạn 30/9."],"mock":{"title":"Techcombank-style practice test","topics":{"Quant":6,"Logical":6,"Verbal":6,"DI":6,"SJT":0},"minutes":30,"navigation":true,"note":"Techcombank xác nhận có Aptitude Test nhưng chưa công bố định dạng; cấu hình cân bằng 4 mảng là mô phỏng chung cho bài aptitude ngân hàng. Functional Test (chuyên môn, coding) và Assessment Center không mô phỏng được trong app.","basis":"general","src":[0]},"pitfalls":["Nhầm tên năm: 'TFG 2027' là đợt tuyển năm 2026 (onboarding 1/2027) (official).","Ứng tuyển dù không thể chuyển ra Hà Nội — tất cả vị trí TFG 2027 ở Hội sở Hà Nội (official).","Chỉ ôn aptitude mà bỏ qua Functional Test theo stream (official).","Chờ đến tháng 9 mới nộp: Remote Interview và các bài test bắt đầu từ tháng 8 (official).","Thiếu chuẩn bị tiếng Anh cho test và phỏng vấn (general)."],"sources":[{"title":"TECHCOMBANK FUTURE GEN 2027","url":"https://tuyendung.techcombankjobs.com/techcombank-future-gen","publisher":"Techcombank","year":"2026","accessed":"2026-11-13"},{"title":"Chương Trình Tuyển Dụng Quản Trị Viên Tập Sự 'Techcombank Future Gen 2027' (Công Nghệ, Dữ Liệu & AI, Kinh Doanh, Quản Trị Chung)","url":"https://ybox.vn/tuyen-dung/toan-quoc-chuong-trinh-tuyen-dung-quan-tri-vien-tap-su-techcombank-future-gen-2027-tai-ngan-hang-ky-thuong-viet-nam-techcombank-danh-cho-sinh-vien-nam-cuoi-hoac-duoi-2-nam-kinh-nghiem-cong-nghe-du-lieu-and-ai-kinh-doanh-quan-tri-chung-6a6c05edc4b4780eb131d97f","publisher":"YBOX","year":"2026","accessed":"2026-11-13"},{"title":"Techcombank Future Gen 2025: Chương trình Quản trị viên Tập sự mùa thứ 4 - đổi mới từ nguồn nhân lực trẻ tài năng","url":"https://baodautu.vn/techcombank-future-gen-2025-chuong-trinh-quan-tri-vien-tap-su-mua-thu-4---doi-moi-tu-nguon-nhan-luc-tre-tai-nang-d218605.html","publisher":"Báo Đầu tư","year":"2024","accessed":"2026-11-13"},{"title":"Cơ hội trở thành quản trị viên tập sự làm việc tại Techcombank","url":"https://tuoitre.vn/co-hoi-tro-thanh-quan-tri-vien-tap-su-lam-viec-tai-techcombank-20250815192630868.htm","publisher":"Tuổi Trẻ Online","year":"2025","accessed":"2026-11-13"},{"title":"Làm sao để chuẩn bị tốt cho vòng Functional Test Techcombank Future Gen 2027?","url":"https://www.threads.com/@casemate.aud/post/DfTZYBKk_yH/","publisher":"Casemate (Threads, đơn vị luyện thi)","year":"2026","accessed":"2026-11-13"},{"title":"Báo cáo thường niên Techcombank 2022","url":"https://techcombank.com/content/dam/techcombank/public-site/imported-assets/VIE-Book-TCB-AR-22-Web-23063f37a7.pdf","publisher":"Techcombank","year":"2023","accessed":"2026-11-13"}]},{"id":"vpbank","name":"VPBank (Ngân hàng TMCP Việt Nam Thịnh Vượng)","program":"VPBank Young Talents","industry":"Ngân hàng","lastChecked":"2026-11-13","summary":"VPBank Young Talents tuyển sinh viên giỏi sắp tốt nghiệp hoặc dưới 1 năm kinh nghiệm để đào tạo thành chuyên gia và nhân sự chủ chốt; mùa 2026 tuyển 105 Young Talents ở nhiều khối, với lộ trình đào tạo cá nhân hóa 15 tháng đầu. Quy trình chính thức 2026: Sơ loại hồ sơ → Kiểm tra năng lực → Phỏng vấn nhóm → Phỏng vấn cá nhân → Gia nhập. Có kênh vào thẳng vòng cuối qua học bổng Future VPBanker. (Một tin đăng bên thứ ba cho mùa 2025 nêu cam kết làm việc tối thiểu 3 năm – chưa xác minh.)","intake":{"text":"Young Talents 2026 (chính thức): thời gian tuyển chọn tháng 4–8/2026, xét tuyển nhiều đợt; Sơ loại hồ sơ đến 05/06/2026; Kiểm tra năng lực từ tháng 5; Phỏng vấn nhóm từ tháng 6; Phỏng vấn cá nhân từ tháng 7; gia nhập từ tháng 8/2026. Mùa 2025 mở đơn từ khoảng tháng 5/2025 (chi tiết lịch 2025 chưa xác minh được). Hai mùa gần nhất mở đơn khoảng tháng 4–5 (suy luận).","basis":"official","src":[0]},"eligibility":[{"text":"Sinh viên xuất sắc đang học năm cuối, mới tốt nghiệp cử nhân hoặc thạc sĩ, dưới 1 năm kinh nghiệm; làm việc tại TP. Hà Nội và TP.HCM (2026).","basis":"official","src":[0]},{"text":"Cam kết làm việc tối thiểu 03 năm tại VPBank — chỉ thấy trong tin đăng TopCV mùa 2025, không có trên trang chính thức 2026 (reported, chưa xác minh).","basis":"reported","src":[1]},{"text":"Kênh ưu tiên: học bổng Future VPBanker 2026 (sinh viên năm 3, năm cuối) → tuyển thẳng vào vòng phỏng vấn cuối Young Talents 2027. Trước đó: Future VPBanker 2025 → vòng phỏng vấn cuối YT 2026; thí sinh vào chung kết VPBank Technology Hackathon 2025 (Junior track) được tuyển thẳng vào YT 2025 (theo báo chí).","basis":"reported","src":[2,3,4]}],"functions":[{"text":"YT 2026 tuyển 105 Young Talents ở nhiều khối: Công nghệ thông tin, Quản trị & Phân tích dữ liệu (EDA, gồm AI Factory), Khách hàng doanh nghiệp (CMB), KHDN lớn & đầu tư (CIB), KHDN vừa và nhỏ (SME), Quản trị rủi ro, Tài chính, Nguồn vốn & Thị trường tài chính, Kiểm toán nội bộ, Quản trị nguồn nhân lực, Pháp chế & Kiểm soát tuân thủ, Truyền thông & Tiếp thị, Quản lý đối tác & Quan hệ đối ngoại, Vận hành, Thu hồi & Xử lý nợ… Vị trí ARM hướng tới trở thành ARM chính thức sau 8–15 tháng tùy kết quả đánh giá.","basis":"official","src":[0]}],"stages":[{"name":"Sơ loại hồ sơ (Online application)","what":"Nộp hồ sơ online trên trang VPBank Young Talents (2026: đến 05/06/2026, xét nhiều đợt); chọn khối mong muốn.","tips":["Chọn khối phù hợp chuyên ngành và nêu rõ lý do.","Nộp sớm vì việc xét tuyển diễn ra nhiều đợt."],"basis":"official","src":[0]},{"name":"Kiểm tra năng lực (Online test)","what":"Bài kiểm tra năng lực (2026: từ tháng 5). Nội dung, thời lượng và nhà cung cấp chưa được VPBank công bố công khai.","tips":["Luyện bộ aptitude tổng hợp: Quant, Logical, Verbal, DI.","Làm bài ở nơi yên tĩnh, mạng ổn định."],"basis":"official","src":[0]},{"name":"Phỏng vấn nhóm (Group interview)","what":"Phỏng vấn nhóm (2026: từ tháng 6). Hình thức chi tiết: Chưa có thông tin công khai đáng tin cậy.","tips":["Luyện vai trò tổng hợp ý và dẫn dắt nhóm mà không áp đảo.","Đưa ra kết luận có số liệu và đề xuất cụ thể."],"basis":"official","src":[0]},{"name":"Phỏng vấn cá nhân (Final interview)","what":"Phỏng vấn cá nhân (2026: từ tháng 7), sau đó gia nhập VPBank từ tháng 8/2026. Người phỏng vấn: Chưa có thông tin công khai đáng tin cậy.","tips":["Tìm hiểu chiến lược và kết quả kinh doanh gần nhất của VPBank và khối ứng tuyển.","Chuẩn bị trả lời về định hướng gắn bó dài hạn."],"basis":"official","src":[0]}],"tests":[{"name":"Kiểm tra năng lực","provider":null,"format":"Chưa có thông tin công khai đáng tin cậy về số phần, thời gian và dạng câu hỏi; VPBank chỉ công bố tên vòng và thời điểm.","basis":"official","src":[0]}],"values":{"name":"Chưa có thông tin công khai đáng tin cậy","items":[],"basis":"general","src":[]},"prep":["Học Study guide phần aptitude tổng quát và luyện chủ đề Quant/Logical/Verbal/DI.","Mental math gym để tính lãi, tỷ lệ, tăng trưởng nhanh.","Làm 'VPBank-style practice test' trong Mock test 2–3 lần, có bấm giờ.","Luyện SJT để chuẩn bị tư duy tình huống cho phỏng vấn nhóm.","Tìm hiểu khối ứng tuyển (vd. ARM khối khách hàng doanh nghiệp) và các sản phẩm chính.","Nếu còn là sinh viên năm 3/năm cuối, cân nhắc học bổng Future VPBanker — kênh vào thẳng vòng phỏng vấn cuối."],"mock":{"title":"VPBank-style practice test","topics":{"Quant":5,"Logical":5,"Verbal":4,"DI":4,"SJT":2},"minutes":25,"navigation":true,"note":"VPBank chưa công bố định dạng bài kiểm tra năng lực; cấu hình là mô phỏng chung cho bài aptitude ngân hàng, thêm vài câu SJT để chuẩn bị tư duy tình huống cho phỏng vấn nhóm.","basis":"general","src":[0]},"pitfalls":["Không để ý các đợt xét tuyển: 2026 tuyển nhiều đợt và hạn giữa các nguồn khác nhau — luôn lấy mốc trên trang chính thức (official).","Ứng tuyển khi đã có từ 1 năm kinh nghiệm trở lên (official).","Không hỏi rõ điều khoản cam kết thời gian làm việc trước khi nhận offer — một tin đăng mùa 2025 nêu tối thiểu 3 năm (reported, chưa xác minh)."],"sources":[{"title":"VPBank Young Talents 2026","url":"https://hr.vpbank.com.vn/ta/VPBankYoungTalents2026/index.html","publisher":"VPBank","year":"2026","accessed":"2026-11-13"},{"title":"Tuyển VPBank Young Talents 2025 - Chương Trình Tài Năng Trẻ VPBank","url":"https://www.topcv.vn/brand/vpbank/tuyen-dung/vpbank-young-talents-2025-chuong-trinh-tai-nang-tre-vpbank-j1731063.html","publisher":"TopCV","year":"2025","accessed":"2026-11-13"},{"title":"Học Bổng Future VPBanker 2026","url":"https://hr.vpbank.com.vn/ta/FutureVPBanker/index.html","publisher":"VPBank","year":"2026","accessed":"2026-11-13"},{"title":"VPBank trao 54 học bổng Future VPBanker 2025 cho sinh viên xuất sắc","url":"https://tuoitre.vn/vpbank-trao-54-hoc-bong-future-vpbanker-2025-cho-sinh-vien-xuat-sac-20260106145619268.htm","publisher":"Tuổi Trẻ Online","year":"2026","accessed":"2026-11-13"},{"title":"Tỏa sáng vòng chung kết, các tài năng công nghệ trẻ sẵn sàng gia nhập VPBank","url":"https://doanhnhan.baophapluat.vn/toa-sang-vong-chung-ket-cac-tai-nang-cong-nghe-tre-san-sang-gia-nhap-vpbank-85375.html","publisher":"Doanh nhân - Báo Pháp Luật","year":"2025","accessed":"2026-11-13"}]}];
